-- CANDIDATE release file generated by Worker AF (H8) from the tested Stage 2 combined candidate.
-- NOT committed, NOT installed anywhere. Source pieces and hashes: h8/RELEASE_FORM_RESULT.json.
-- Probe/prototype identifiers renamed to production names per h8/tools/rename_map.json.
-- Policy X: no economic-key derivation, freshness or post-Draft behaviour change beyond the tested winners.
-- Repeatable CloudTMS function authority: banking_pay_stage2_source_authorisation_v1
-- Source/expense separation (G01), token finaliser (G02), fan-out generation scope (G03), protected reference V2 (G08,
-- moved from the prototype evidence schema into private), direct-family authorisation (G09), generic authorise (G10),
-- S-02 row-lock gates (A11) and S-07 wait gate (A13).

\set ON_ERROR_STOP on

begin;

-- [NEW] private.bpay_protected_reference_authorisation_signature_v1(p_agency uuid, p_root uuid, p_booking text, p_version integer, p_generation integer, p_lifecycle text, p_hashes text[], p_codec smallint, p_ref jsonb)  winner piece A1_EXTRACT  (tested name evidence_reference_probe.authorisation_signature)
CREATE OR REPLACE FUNCTION private.bpay_protected_reference_authorisation_signature_v1(p_agency uuid, p_root uuid, p_booking text, p_version integer, p_generation integer, p_lifecycle text, p_hashes text[], p_codec smallint, p_ref jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
 IF p_codec=1 AND p_ref IS NULL THEN
  RETURN private.weekly_source_root_authorisation_signature_v1(
   p_agency,p_root,p_booking,p_version,p_generation,p_lifecycle,p_hashes);
 END IF;
 IF p_codec IS DISTINCT FROM 2 OR p_hashes IS NOT NULL OR private.bpay_protected_reference_valid_v1(p_ref) IS NOT TRUE
 THEN RETURN NULL; END IF;
 RETURN (private.weekly_source_root_authorisation_signature_v1(
  p_agency,p_root,p_booking,p_version,p_generation,p_lifecycle,ARRAY[]::text[])
  -'protected_decision_hashes') || jsonb_build_object(
  'binding','WEEKLY_SOURCE_ROOT_AUTHORISATION_SIGNATURE_V2',
  'protected_evidence_reference',p_ref);
END;
$function$;

-- [NEW] private.bpay_protected_reference_capture_v1()  winner piece A1_EXTRACT  (tested name evidence_reference_probe.capture_actual)
CREATE OR REPLACE FUNCTION private.bpay_protected_reference_capture_v1()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE h private.bpay_protected_reference_heads_v1%rowtype; d bytea;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'IMMUTABLE_APPROVAL_DELETE'; END IF;
 IF TG_OP='UPDATE' THEN
   IF ROW(OLD.id,OLD.pay_target_family_id,OLD.approval_hash) IS DISTINCT FROM
      ROW(NEW.id,NEW.pay_target_family_id,NEW.approval_hash) THEN
     RAISE EXCEPTION 'IMMUTABLE_APPROVAL_IDENTITY';
   END IF;
   IF (OLD.withdrawn_at_utc IS NOT NULL)=(NEW.withdrawn_at_utc IS NOT NULL) THEN RETURN NEW; END IF;
 ELSIF (NEW.withdrawn_at_utc IS NOT NULL) THEN RETURN NEW;
 END IF;
 PERFORM private.bpay_protected_reference_try_family_gate_v1(NEW.pay_target_family_id);
 INSERT INTO private.bpay_protected_reference_heads_v1 VALUES
 (NEW.pay_target_family_id,0,private.bpay_protected_reference_genesis_v1(NEW.pay_target_family_id)) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT h FROM private.bpay_protected_reference_heads_v1
 WHERE family_id=NEW.pay_target_family_id FOR UPDATE;
 -- Exactly 16+8+16+32+1+32 bytes after the fixed domain prefix.
 -- This is explicitly NOT the old sorted-set digest.
 d:=sha256(convert_to('BPAY_APPROVAL_REFERENCE_V2_EVENT','UTF8')||
   uuid_send(NEW.pay_target_family_id)||int8send(h.ordinal+1)||uuid_send(NEW.id)||
   NEW.approval_hash||boolsend(NOT (NEW.withdrawn_at_utc IS NOT NULL))||h.digest);
 INSERT INTO private.bpay_protected_reference_events_v1 VALUES
 (NEW.pay_target_family_id,h.ordinal+1,NEW.id,NEW.approval_hash,NOT (NEW.withdrawn_at_utc IS NOT NULL),h.digest,d);
 UPDATE private.bpay_protected_reference_heads_v1 SET ordinal=h.ordinal+1,digest=d
 WHERE family_id=NEW.pay_target_family_id;
 RETURN NEW;
END;
$function$;

-- [NEW] private.bpay_protected_reference_genesis_v1(p_family uuid)  winner piece A1_EXTRACT  (tested name evidence_reference_probe.genesis)
CREATE OR REPLACE FUNCTION private.bpay_protected_reference_genesis_v1(p_family uuid)
 RETURNS bytea
 LANGUAGE sql
 IMMUTABLE STRICT
AS $function$
 SELECT sha256(convert_to('BPAY_APPROVAL_REFERENCE_V2_GENESIS','UTF8')||uuid_send(p_family));
$function$;

-- [NEW] private.bpay_protected_reference_page_v1(p_family uuid, p_cut bigint, p_after bigint, p_limit integer)  winner piece A1_EXTRACT  (tested name evidence_reference_probe.page)
CREATE OR REPLACE FUNCTION private.bpay_protected_reference_page_v1(p_family uuid, p_cut bigint, p_after bigint, p_limit integer)
 RETURNS SETOF private.bpay_protected_reference_events_v1
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
 IF p_limit NOT BETWEEN 1 AND 128 OR p_after<0 OR p_cut<p_after THEN
   RAISE EXCEPTION 'INVALID_AUDIT_PAGE';
 END IF;
 RETURN QUERY SELECT e.* FROM private.bpay_protected_reference_events_v1 e
 WHERE e.family_id=p_family AND e.ordinal>p_after AND e.ordinal<=p_cut
 ORDER BY e.ordinal LIMIT p_limit;
END;
$function$;

-- [NEW] private.bpay_protected_reference_v1(p_family uuid)  winner piece A1_EXTRACT  (tested name evidence_reference_probe.reference)
CREATE OR REPLACE FUNCTION private.bpay_protected_reference_v1(p_family uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE h private.bpay_protected_reference_heads_v1%rowtype;
BEGIN
 PERFORM private.bpay_protected_reference_try_family_gate_v1(p_family);
 INSERT INTO private.bpay_protected_reference_heads_v1 VALUES
 (p_family,0,private.bpay_protected_reference_genesis_v1(p_family)) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT h FROM private.bpay_protected_reference_heads_v1 WHERE family_id=p_family FOR UPDATE;
 RETURN jsonb_build_object('format','BPAY_APPROVAL_REFERENCE_V2','family_id',p_family,
   'ordinal',h.ordinal,'digest',encode(h.digest,'hex'));
END;
$function$;

-- [NEW] private.bpay_protected_reference_for_root_v1(p_root uuid)  winner piece A1_EXTRACT  (tested name evidence_reference_probe.reference_for_root)
CREATE OR REPLACE FUNCTION private.bpay_protected_reference_for_root_v1(p_root uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE f uuid;
BEGIN
 SELECT family.id INTO f FROM public.timesheets t
 JOIN public.weekly_exceptional_pay_target_families family
 ON btrim(family.root_family_booking_id)=btrim(t.booking_id)
 AND family.root_family_booking_id=t.booking_id
 WHERE t.timesheet_id=p_root;
 IF f IS NULL THEN
   RETURN jsonb_build_object('format','BPAY_APPROVAL_REFERENCE_V2','family_id',null,
    'ordinal',0,'digest',encode(sha256(convert_to('BPAY_APPROVAL_REFERENCE_V2_EMPTY','UTF8')),'hex'));
 END IF;
 RETURN private.bpay_protected_reference_v1(f);
END;
$function$;

-- [NEW] private.bpay_protected_reference_valid_v1(p_ref jsonb)  winner piece A1_EXTRACT  (tested name evidence_reference_probe.reference_valid)
CREATE OR REPLACE FUNCTION private.bpay_protected_reference_valid_v1(p_ref jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE f uuid; n bigint; d bytea;
BEGIN
 IF p_ref IS NULL OR jsonb_typeof(p_ref)<>'object' OR
 p_ref->>'format' IS DISTINCT FROM 'BPAY_APPROVAL_REFERENCE_V2' OR
 NOT (p_ref ?& ARRAY['format','family_id','ordinal','digest']) OR
 (SELECT count(*) FROM jsonb_object_keys(p_ref))<>4 OR
 jsonb_typeof(p_ref->'ordinal')<>'number' OR
 jsonb_typeof(p_ref->'digest')<>'string' THEN RETURN false; END IF;
 n:=(p_ref->>'ordinal')::bigint; d:=decode(p_ref->>'digest','hex');
 IF n<0 OR octet_length(d)<>32 THEN RETURN false; END IF;
 IF p_ref->'family_id'='null'::jsonb THEN
   RETURN n=0 AND d=sha256(convert_to('BPAY_APPROVAL_REFERENCE_V2_EMPTY','UTF8'));
 END IF;
 IF jsonb_typeof(p_ref->'family_id')<>'string' THEN RETURN false; END IF;
 f:=(p_ref->>'family_id')::uuid;
 IF n=0 THEN
   RETURN d=private.bpay_protected_reference_genesis_v1(f) AND EXISTS
    (SELECT 1 FROM private.bpay_protected_reference_heads_v1 WHERE family_id=f);
 END IF;
 RETURN EXISTS(SELECT 1 FROM private.bpay_protected_reference_events_v1
  WHERE family_id=f AND ordinal=n AND digest=d);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
 RETURN false;
END;
$function$;

-- [NEW] private.bpay_protected_reference_try_family_gate_v1(p_family uuid)  winner piece A1_EXTRACT  (tested name evidence_reference_probe.try_family_gate)
CREATE OR REPLACE FUNCTION private.bpay_protected_reference_try_family_gate_v1(p_family uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
 -- Nonblocking: a reference cannot wait holding financial locks for a writer
 -- that might itself need those locks later. Hash collisions only refuse work.
 IF NOT pg_try_advisory_xact_lock(hashtextextended(
   'BPAY_APPROVAL_REFERENCE_V2:'||p_family::text,0)) THEN
  RAISE EXCEPTION 'BPAY_APPROVAL_EVIDENCE_BUSY' USING ERRCODE='55P03';
 END IF;
END;
$function$;

-- [NEW] private._candidate_expense_source_family_v1(p_timesheet_id uuid)  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private._candidate_expense_source_family_v1(p_timesheet_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE
  v_source boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM public.timesheets t
    WHERE t.timesheet_id=p_timesheet_id
      AND t.sheet_scope='WEEKLY'::public.timesheet_scope_enum
      AND t.line_type='HOURS'::public.timesheet_line_type_enum
      AND NOT t.is_adjustment
      -- Ownership is not payment eligibility. Withdrawal/archive does not
      -- turn an imported Timesheet into an ordinary expense-claim carrier.
      AND t.settings_authority_version='CONTRACT_SETTINGS_AUTHORITY_V1'
      AND t.settings_authority_resolved_at IS NOT NULL
      AND (
        t.settings_authority_json#>'{applicability,import_authoritative}'='true'::jsonb
        -- User-confirmed domain: self_bill IS import-authoritative. An import
        -- label or separate-expense preference alone is not sufficient.
        OR t.settings_authority_json#>'{values,self_bill}'='true'::jsonb
        OR EXISTS (
          SELECT 1 FROM public.weekly_source_row_timesheet_lineages l
          WHERE l.family_booking_id=t.booking_id
            AND t.booking_id IS NOT NULL AND t.booking_id<>''
        )
      )
      AND EXISTS (
        SELECT 1 FROM public.contract_weeks cw
        WHERE cw.contract_id=t.contract_id AND cw.week_ending_date=t.week_ending_date
          AND cw.additional_seq=0 AND NOT cw.is_adjustment
          AND cw.timesheet_id=t.timesheet_id
      )
  ) INTO v_source;
  IF v_source AND EXISTS (
    SELECT 1 FROM public.candidate_expense_components c
    WHERE c.owning_timesheet_id=p_timesheet_id
      AND c.lifecycle_state NOT IN
        ('MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED')
  ) THEN
    RAISE EXCEPTION 'SOURCE_ROOT_HAS_SEPARATE_CLAIM_COMPONENT'
      USING ERRCODE='55000';
  END IF;
  RETURN v_source;
END;
$function$;

-- [NEW] private._candidate_expense_source_root_guard_v1()  winner piece A11_S02
CREATE OR REPLACE FUNCTION private._candidate_expense_source_root_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF NEW.lifecycle_state NOT IN
  ('MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED') THEN
  IF NEW.owning_timesheet_id IS NOT NULL
  AND (TG_OP='INSERT' OR NEW.owning_timesheet_id IS DISTINCT FROM OLD.owning_timesheet_id)
  AND NOT EXISTS (SELECT 1 FROM public.timesheets t WHERE t.timesheet_id=NEW.owning_timesheet_id) THEN
   RAISE EXCEPTION 'BPAY_EXPENSE_TIMESHEET_NOT_VISIBLE' USING ERRCODE='23503';
  END IF;
  PERFORM private.bpay_expense_identity_gate_v1(NEW.owning_timesheet_id);
  IF private._candidate_expense_source_family_v1(NEW.owning_timesheet_id) THEN
   RAISE EXCEPTION 'SOURCE_ROOT_HAS_SEPARATE_CLAIM_COMPONENT' USING ERRCODE='55000';
  END IF;
 END IF;
 RETURN NEW;
END; $function$;

-- [NEW] private.bpay_authorisation_work_reference_v1()  winner piece A1_EXTRACT  (tested name private.bpay_authorisation_work_reference_probe)
CREATE OR REPLACE FUNCTION private.bpay_authorisation_work_reference_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 SELECT bpay_work_revision_v1 INTO STRICT NEW.bpay_root_work_revision_v1
 FROM public.timesheets WHERE timesheet_id=NEW.root_timesheet_id;
 RETURN NEW;
END;
$function$;

-- [NEW] private.bpay_expense_classification_lineage_v1()  winner piece A11_S02  (tested name private.bpay_expense_classification_lineage_probe)
CREATE OR REPLACE FUNCTION private.bpay_expense_classification_lineage_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE item record; n integer:=0;
BEGIN
 -- Lineages are otherwise immutable. Existing family gate is also retained.
 IF TG_WHEN='BEFORE' THEN
  PERFORM private.bpay_source_family_try_lock_v1(NEW.family_booking_id);
  IF NEW.timesheet_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM public.timesheets t WHERE t.timesheet_id=NEW.timesheet_id) THEN
   RAISE EXCEPTION 'BPAY_EXPENSE_TIMESHEET_NOT_VISIBLE' USING ERRCODE='23503';
  END IF;
  PERFORM private.bpay_expense_identity_gate_v1(NEW.timesheet_id);
 ELSE
  PERFORM private._candidate_expense_source_family_v1(NEW.timesheet_id);
 END IF;
 -- S-02: native lock on the family's current row, re-verified (a rotation in flight => BUSY).
 PERFORM private.bpay_source_family_current_gate_v1(NEW.family_booking_id);
 FOR item IN SELECT t.timesheet_id FROM public.timesheets t
  WHERE t.booking_id=NEW.family_booking_id AND t.is_current LIMIT 2
 LOOP
  n:=n+1;
  IF n>1 THEN RAISE EXCEPTION 'CURRENT_ROW_CARDINALITY' USING ERRCODE='55000'; END IF;
  IF TG_WHEN='BEFORE' THEN
   PERFORM private.bpay_expense_identity_gate_v1(item.timesheet_id);
  ELSE
   PERFORM private._candidate_expense_source_family_v1(item.timesheet_id);
  END IF;
 END LOOP;
 RETURN NEW;
END; $function$;

-- [NEW] private.bpay_expense_classification_ts_v1()  winner piece A11_S02  (tested name private.bpay_expense_classification_ts_probe)
CREATE OR REPLACE FUNCTION private.bpay_expense_classification_ts_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF TG_WHEN='BEFORE' THEN
  -- S-02: an ordinary classification write holds this row's own row lock, which every claim/week/lineage
  -- writer must share-lock before deciding; only a booking change needs the (old and new) family locks.
  IF TG_OP='UPDATE' AND OLD.booking_id IS DISTINCT FROM NEW.booking_id THEN
   PERFORM private.bpay_source_family_try_lock_v1(OLD.booking_id);
   PERFORM private.bpay_source_family_try_lock_v1(NEW.booking_id);
  END IF;
 ELSE
  PERFORM private._candidate_expense_source_family_v1(NEW.timesheet_id);
 END IF;
 RETURN NEW;
END; $function$;

-- [NEW] private.bpay_expense_classification_week_v1()  winner piece A13  (tested name private.bpay_expense_classification_week_probe)
CREATE OR REPLACE FUNCTION private.bpay_expense_classification_week_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE old_ts uuid; new_ts uuid; lock_id uuid;
BEGIN
 IF TG_WHEN='BEFORE' THEN
  -- S-07 (a): an UPDATE that changes no Stage 2 decision input read from contract_weeks takes no gate.
  -- Status is not an input (it changes only a refusal reason, never an allow/refuse outcome).
  IF TG_OP='UPDATE'
     AND NEW.timesheet_id IS NOT DISTINCT FROM OLD.timesheet_id
     AND NEW.contract_id IS NOT DISTINCT FROM OLD.contract_id
     AND NEW.week_ending_date IS NOT DISTINCT FROM OLD.week_ending_date
     AND NEW.additional_seq IS NOT DISTINCT FROM OLD.additional_seq
     AND NEW.is_adjustment IS NOT DISTINCT FROM OLD.is_adjustment
  THEN
   RETURN NEW;
  END IF;
  -- A5 V2 / S-02 refusal of a new reference to a Timesheet this transaction cannot see (unchanged).
  IF TG_OP<>'DELETE' THEN
   IF NEW.timesheet_id IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM public.timesheets t WHERE t.timesheet_id=NEW.timesheet_id) THEN
    IF TG_OP='INSERT' THEN RAISE EXCEPTION 'BPAY_EXPENSE_TIMESHEET_NOT_VISIBLE' USING ERRCODE='23503'; END IF;
    IF NEW.timesheet_id IS DISTINCT FROM OLD.timesheet_id THEN RAISE EXCEPTION 'BPAY_EXPENSE_TIMESHEET_NOT_VISIBLE' USING ERRCODE='23503'; END IF;
   END IF;
  END IF;
  -- S-07 (b): WAIT for the old and new bound Timesheet rows (lower id first), then re-read the new binding.
  IF TG_OP<>'INSERT' THEN old_ts:=OLD.timesheet_id; END IF;
  IF TG_OP='INSERT' THEN new_ts:=NEW.timesheet_id;
  ELSIF TG_OP='UPDATE' AND NEW.timesheet_id IS DISTINCT FROM OLD.timesheet_id THEN new_ts:=NEW.timesheet_id;
  END IF;
  FOR lock_id IN SELECT x FROM unnest(ARRAY[old_ts,new_ts]) x WHERE x IS NOT NULL ORDER BY x LOOP
   IF NOT private.bpay_source_row_wait_gate_v1(lock_id) AND lock_id=new_ts THEN
    RAISE EXCEPTION 'BPAY_EXPENSE_TIMESHEET_NOT_VISIBLE' USING ERRCODE='23503';
   END IF;
  END LOOP;
 ELSE
  PERFORM private._candidate_expense_source_family_v1(NEW.timesheet_id);
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END; $function$;

-- [NEW] private.bpay_expense_identity_gate_v1(p_id uuid)  winner piece A11_S02  (tested name private.bpay_expense_identity_gate_probe)
CREATE OR REPLACE FUNCTION private.bpay_expense_identity_gate_v1(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE booking text; seen boolean; recheck text; locked boolean;
BEGIN
 IF p_id IS NULL THEN RETURN; END IF;
 SELECT t.booking_id INTO booking FROM public.timesheets t WHERE t.timesheet_id=p_id;
 seen:=FOUND;
 IF seen AND btrim(booking)<>'' THEN
  PERFORM private.bpay_source_family_try_lock_v1(booking);
 ELSIF NOT pg_try_advisory_xact_lock(hashtext('BPAY_EXPENSE_IDENTITY_V1'),hashtext(p_id::text)) THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
 -- S-02: ordinary Timesheet writers no longer take the family/identity lock, so the claim/lineage writer
 -- share-locks the row itself (prompt BUSY if an ordinary writer holds it) and re-reads under that lock.
 locked:=private.bpay_source_row_gate_v1(p_id,false);
 SELECT t.booking_id INTO recheck FROM public.timesheets t WHERE t.timesheet_id=p_id;
 IF FOUND IS DISTINCT FROM seen OR recheck IS DISTINCT FROM booking THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
END; $function$;

-- [NEW] private.bpay_lineage_work_binding_v1()  winner piece A1_EXTRACT  (tested name private.bpay_lineage_work_binding_probe)
CREATE OR REPLACE FUNCTION private.bpay_lineage_work_binding_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$ DECLARE work_key text; BEGIN
 SELECT booking_id,bpay_work_revision_v1 INTO STRICT work_key,NEW.bpay_lineage_work_revision_v1
 FROM public.timesheets WHERE timesheet_id=NEW.timesheet_id;
 IF work_key IS DISTINCT FROM NEW.family_booking_id THEN
 RAISE EXCEPTION 'BPAY_LINEAGE_WORK_IDENTITY_MISMATCH' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $function$;

-- [NEW] private.bpay_protected_family_for_current_v1(p_id uuid)  winner piece A1_EXTRACT  (tested name private.bpay_protected_family_for_current_probe)
CREATE OR REPLACE FUNCTION private.bpay_protected_family_for_current_v1(p_id uuid)
 RETURNS TABLE(family_id uuid, agency_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
SELECT f.id,f.agency_id FROM public.timesheets t
JOIN public.weekly_exceptional_pay_target_families f
 ON btrim(f.root_family_booking_id)=btrim(t.booking_id) AND f.root_family_booking_id=t.booking_id
WHERE t.timesheet_id=p_id AND t.booking_id IS NOT NULL AND btrim(t.booking_id)<>'';
$function$;

-- [NEW] private.bpay_protected_root_reference_v1()  winner piece A1_EXTRACT  (tested name private.bpay_protected_root_reference_probe)
CREATE OR REPLACE FUNCTION private.bpay_protected_root_reference_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 SELECT bpay_work_revision_v1 INTO STRICT NEW.bpay_root_work_revision_v1
 FROM public.timesheets WHERE timesheet_id=NEW.root_timesheet_id;
 RETURN NEW;
END;
$function$;

-- [NEW] private.bpay_source_family_current_gate_v1(p_booking text)  winner piece A11_S02  (tested name private.bpay_s02_family_current_gate_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_family_current_gate_v1(p_booking text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE locked uuid[]; visible uuid[];
BEGIN
 -- S-02: share-lock the family's CURRENT Timesheet row(s), then re-verify with a fresh snapshot that the
 -- locked set is exactly the current set. A rotation/delete in flight holds that row => refused (BUSY);
 -- a rotation committed meanwhile is seen by the re-read (EvalPlanQual re-checks is_current/booking).
 IF p_booking IS NULL OR btrim(p_booking)='' THEN RETURN; END IF;
 SELECT coalesce(array_agg(q.timesheet_id ORDER BY q.timesheet_id),'{}'::uuid[]) INTO locked
 FROM (SELECT t.timesheet_id FROM public.timesheets t
       WHERE t.booking_id=p_booking AND t.is_current FOR SHARE SKIP LOCKED) q;
 SELECT coalesce(array_agg(t.timesheet_id ORDER BY t.timesheet_id),'{}'::uuid[]) INTO visible
 FROM public.timesheets t WHERE t.booking_id=p_booking AND t.is_current;
 IF locked IS DISTINCT FROM visible THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
END; $function$;

-- [NEW] private.bpay_source_row_gate_v1(p_id uuid, p_exclusive boolean)  winner piece A11_S02  (tested name private.bpay_s02_row_gate_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_row_gate_v1(p_id uuid, p_exclusive boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 -- S-02: native row lock on one Timesheet (tuple lock, no lock-table slot). SHARE conflicts with every
 -- UPDATE/DELETE of the row; NO KEY UPDATE also conflicts with SHARE holders. SKIP LOCKED never waits:
 -- a visible row held by another writer is refused promptly, exactly like the family try-lock.
 -- Returns false only when the row is not visible to this transaction (caller decides).
 IF p_id IS NULL THEN RETURN false; END IF;
 IF p_exclusive THEN
  PERFORM 1 FROM public.timesheets t WHERE t.timesheet_id=p_id FOR NO KEY UPDATE SKIP LOCKED;
 ELSE
  PERFORM 1 FROM public.timesheets t WHERE t.timesheet_id=p_id FOR SHARE SKIP LOCKED;
 END IF;
 IF FOUND THEN RETURN true; END IF;
 IF EXISTS (SELECT 1 FROM public.timesheets t WHERE t.timesheet_id=p_id) THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
 RETURN false;
END; $function$;

-- [NEW] private.bpay_source_row_wait_gate_v1(p_id uuid)  winner piece A13  (tested name private.bpay_s07_row_wait_gate_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_row_wait_gate_v1(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 -- S-07: WAITING native row lock on one Timesheet for Contract Week writers (tuple lock, no lock-table slot).
 -- NO KEY UPDATE conflicts with FOR SHARE holders (claims, lineage, guard, authorisation) and with every
 -- UPDATE/DELETE of the row. No SKIP LOCKED: the writer queues like any pre-Stage-2 row write, bounded by
 -- lock_timeout, with deadlocks detected by PostgreSQL (40P01). Under READ COMMITTED the locking read returns
 -- the latest committed version after the wait.
 -- Returns false only when the row is not visible (never visible, or deleted by a transaction that committed
 -- while this one waited); the caller decides.
 IF p_id IS NULL THEN RETURN false; END IF;
 PERFORM 1 FROM public.timesheets t WHERE t.timesheet_id=p_id FOR NO KEY UPDATE;
 RETURN FOUND;
END; $function$;

-- [NEW] private.bpay_source_auth_family_gate_v1()  winner piece A11_S02  (tested name private.bpay_source_auth_family_gate_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_auth_family_gate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$ BEGIN
 IF TG_OP<>'INSERT' THEN
  PERFORM private.bpay_source_family_try_lock_v1(OLD.family_booking_id);
 END IF;
 IF TG_OP<>'DELETE' THEN
  PERFORM private.bpay_source_family_try_lock_v1(NEW.family_booking_id);
 END IF;
 -- S-02: native share locks on the root row and the family's current row (ordinary writers take none).
 IF TG_OP<>'INSERT' THEN
  PERFORM private.bpay_source_row_gate_v1(OLD.root_timesheet_id,false);
  PERFORM private.bpay_source_family_current_gate_v1(OLD.family_booking_id);
 END IF;
 IF TG_OP<>'DELETE' THEN
  PERFORM private.bpay_source_row_gate_v1(NEW.root_timesheet_id,false);
  PERFORM private.bpay_source_family_current_gate_v1(NEW.family_booking_id);
  RETURN NEW;
 END IF;
 RETURN OLD;
END; $function$;

-- [NEW] private.bpay_source_authorise_identity_v1(p_id uuid)  winner piece A2  (tested name private.bpay_source_authorise_identity_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_authorise_identity_v1(p_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path=pg_catalog,public,private,pg_temp AS $fn$
DECLARE requested_booking text; current_id uuid; current_version integer; current_contract uuid;
 candidate uuid; financial_candidate uuid; cw_count integer; other_root uuid;
 failure text;
BEGIN
 IF p_id IS NULL THEN failure:='ROOT_ID_REQUIRED';
 ELSE
  SELECT booking_id INTO requested_booking FROM public.timesheets WHERE timesheet_id=p_id;
  IF NOT FOUND OR requested_booking IS NULL OR btrim(requested_booking)=''
  THEN failure:='BOOKING_IDENTITY_MISSING'; END IF;
 END IF;
 IF failure IS NOT NULL THEN
  RETURN jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
   'retryable',false,'reason',failure);
 END IF;
 -- A missing directory is an installation/invariant failure, not an empty
 -- historical domain. No lazy scan/backfill in this financial operation.
 IF NOT EXISTS(SELECT 1 FROM private.bpay_clock_rows_v1 r
  JOIN private.bpay_clock_families_v1 f ON f.id=r.family_id
  WHERE r.timesheet_id=p_id AND f.booking_id=requested_booking) THEN
  RAISE EXCEPTION 'BPAY_SOURCE_DIRECTORY_NOT_READY' USING ERRCODE='55000';
 END IF;
 IF EXISTS(SELECT 1 FROM private.bpay_clock_families_v1 f
  WHERE btrim(f.booking_id)=btrim(requested_booking)
    AND f.booking_id<>requested_booking) THEN
  RETURN jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
   'retryable',false,'reason','BOOKING_REFERENCE_CANONICAL_COLLISION');
 END IF;
 SELECT timesheet_id,version,contract_id INTO current_id,current_version,current_contract FROM public.timesheets
 WHERE booking_id=requested_booking AND is_current;
 IF NOT FOUND OR current_version IS NULL THEN
  RETURN jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
   'retryable',false,'reason','CANONICAL_AMBIGUOUS');
 END IF;
 SELECT candidate_id INTO candidate FROM public.contracts WHERE id=current_contract;
 -- uq_tsfin_current guarantees at most one row; do not count obsolete TSFINs.
 SELECT candidate_id INTO financial_candidate FROM public.timesheets_financials
 WHERE timesheet_id=current_id AND is_current;
 IF candidate IS NULL OR (financial_candidate IS NOT NULL AND financial_candidate<>candidate) THEN
  RETURN jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
   'retryable',false,'reason','CANDIDATE_UNRESOLVED',
   'family_booking_id',requested_booking,'canonical_timesheet_id',current_id);
 END IF;
 SELECT count(*) INTO cw_count FROM
 (SELECT id FROM public.contract_weeks WHERE timesheet_id=current_id LIMIT 2) q;
 IF cw_count>1 THEN
  RETURN jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
   'retryable',false,'reason','CONTRACT_WEEK_CARDINALITY',
   'family_booking_id',requested_booking,'canonical_timesheet_id',current_id);
 END IF;
 SELECT root_timesheet_id INTO other_root FROM public.weekly_source_root_authorisations
 WHERE family_booking_id=requested_booking AND withdrawn_at_utc IS NULL
 AND root_timesheet_id<>current_id;
 IF other_root IS NOT NULL THEN
  RETURN jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
   'retryable',false,'reason','LIVE_AUTHORISATION_NOT_ON_CANONICAL_ROW',
   'family_booking_id',requested_booking,'canonical_timesheet_id',current_id);
 END IF;
 RETURN jsonb_build_object('ok',true,'candidate_id',candidate,
  'requested_timesheet_id',p_id,'family_booking_id',requested_booking,
  'canonical_timesheet_id',current_id,'canonical_version',current_version,
  'requested_is_canonical',p_id=current_id,
  'family_is_current',p_id=current_id);
END;
$fn$;

-- [NEW] private.bpay_source_authorise_lock_v1(p_candidate uuid, p_id uuid, p_job uuid)  winner piece A1_EXTRACT  (tested name private.bpay_source_authorise_lock_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_authorise_lock_v1(p_candidate uuid, p_id uuid, p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE gate jsonb; before_booking text; after_booking text; identity jsonb; requested_candidate uuid;
BEGIN
 gate:=private.weekly_source_candidate_serial_gate_v1(p_candidate,
  'WORKBENCH_CANDIDATE_FIRST_AUTHORISATION',p_job,'WEEKLY_SOURCE_FIRST_AUTHORISATION');
 IF coalesce((gate->>'ok')::boolean,false) IS NOT TRUE THEN RETURN gate; END IF;
 SELECT booking_id INTO before_booking FROM public.timesheets WHERE timesheet_id=p_id;
 IF before_booking IS NULL OR btrim(before_booking)='' THEN
  RETURN jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
   'retryable',false,'reason','BOOKING_IDENTITY_MISSING');
 END IF;
 -- Exact existing rotation advisory keys, BEFORE the single requested row.
 PERFORM pg_advisory_xact_lock(hashtext(btrim(before_booking)));
 IF before_booking<>btrim(before_booking) THEN
  PERFORM pg_advisory_xact_lock(hashtext(before_booking));
 END IF;
 SELECT booking_id INTO after_booking FROM public.timesheets WHERE timesheet_id=p_id FOR UPDATE;
 IF NOT FOUND OR after_booking IS DISTINCT FROM before_booking THEN
  RETURN jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
   'retryable',false,'reason','BOOKING_REPOINTED_DURING_LOCK');
 END IF;
 SELECT c.candidate_id INTO requested_candidate FROM public.timesheets t
 LEFT JOIN public.contracts c ON c.id=t.contract_id WHERE t.timesheet_id=p_id;
 identity:=private.bpay_source_authorise_identity_v1(p_id);
 IF coalesce((identity->>'ok')::boolean,false) IS NOT TRUE THEN RETURN identity; END IF;
 IF requested_candidate IS DISTINCT FROM p_candidate
    OR (identity->>'candidate_id')::uuid IS DISTINCT FROM p_candidate THEN
  RETURN jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
   'retryable',false,'reason','ROOT_CANDIDATE_MISMATCH');
 END IF;
 RETURN jsonb_build_object('ok',true,'gate','GRANTED','families',jsonb_build_array(identity));
END;
$function$;

-- [NEW] private.bpay_source_family_try_lock_v1(p_booking text)  winner piece A1_EXTRACT  (tested name private.bpay_source_family_try_lock_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_family_try_lock_v1(p_booking text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 IF p_booking IS NULL OR btrim(p_booking)='' THEN RETURN; END IF;
 -- Nonblocking acquisition is essential for row-trigger callers: never wait
 -- for a family lock while retaining a row lock wanted by that family owner.
 IF NOT pg_try_advisory_xact_lock(hashtext(btrim(p_booking))) THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
 IF p_booking<>btrim(p_booking)
 AND NOT pg_try_advisory_xact_lock(hashtext(p_booking)) THEN
  RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
 END IF;
END; $function$;

-- [NEW] private.bpay_source_lineage_family_gate_v1()  winner piece A1_EXTRACT  (tested name private.bpay_source_lineage_family_gate_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_lineage_family_gate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$ BEGIN
 PERFORM private.bpay_source_family_try_lock_v1(NEW.family_booking_id);
 RETURN NEW;
END; $function$;

-- [NEW] private.bpay_source_protected_family_gate_v1()  winner piece A11_S02  (tested name private.bpay_source_protected_family_gate_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_protected_family_gate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$ BEGIN
 IF TG_OP<>'INSERT' THEN
  PERFORM private.bpay_source_family_try_lock_v1(OLD.root_family_booking_id);
 END IF;
 IF TG_OP<>'DELETE' THEN
  PERFORM private.bpay_source_family_try_lock_v1(NEW.root_family_booking_id);
 END IF;
 -- S-02: native share locks on the root row and the family's current row (ordinary writers take none).
 IF TG_OP<>'INSERT' THEN
  PERFORM private.bpay_source_row_gate_v1(OLD.root_timesheet_id,false);
  PERFORM private.bpay_source_family_current_gate_v1(OLD.root_family_booking_id);
 END IF;
 IF TG_OP<>'DELETE' THEN
  PERFORM private.bpay_source_row_gate_v1(NEW.root_timesheet_id,false);
  PERFORM private.bpay_source_family_current_gate_v1(NEW.root_family_booking_id);
  RETURN NEW;
 END IF;
 RETURN OLD;
END; $function$;

-- [NEW] private.bpay_source_timesheet_family_gate_v1()  winner piece A11_S02  (tested name private.bpay_source_timesheet_family_gate_probe)
CREATE OR REPLACE FUNCTION private.bpay_source_timesheet_family_gate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$ BEGIN
 -- S-02: an ordinary insert, delete or rotation (is_current/version) takes no advisory lock. Rotations and
 -- deletes UPDATE/DELETE the family's current row, so Source events that share-lock that row serialise with
 -- them natively; a new row is invisible to every Source event until it commits (23503 NOT_VISIBLE).
 -- The family lock remains for a booking change (both families) and for a non-canonical booking whose
 -- whitespace variant collides with its trimmed family.
 IF TG_OP='UPDATE' AND OLD.booking_id IS DISTINCT FROM NEW.booking_id THEN
  PERFORM private.bpay_source_family_try_lock_v1(OLD.booking_id);
  PERFORM private.bpay_source_family_try_lock_v1(NEW.booking_id);
 ELSIF TG_OP<>'INSERT' AND OLD.booking_id<>btrim(OLD.booking_id) THEN
  PERFORM private.bpay_source_family_try_lock_v1(OLD.booking_id);
 ELSIF TG_OP<>'DELETE' AND NEW.booking_id<>btrim(NEW.booking_id) THEN
  PERFORM private.bpay_source_family_try_lock_v1(NEW.booking_id);
 END IF;
 IF TG_OP<>'DELETE' THEN RETURN NEW; END IF;
 RETURN OLD;
END; $function$;

-- [REPLACES] private._candidate_expense_components_sync_financial_v1(p_timesheet_id uuid, p_now_utc timestamp with time zone)  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private._candidate_expense_components_sync_financial_v1(p_timesheet_id uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_fin public.timesheets_financials%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_component public.candidate_expense_components%rowtype;
  v_before jsonb;
  v_agency text;
  v_count integer:=0;
begin
  if private._candidate_expense_source_family_v1(p_timesheet_id) then
    return jsonb_build_object('ok',true,'timesheet_id',p_timesheet_id,'component_count',0);
  end if;
  select * into v_timesheet from public.timesheets row
  where row.timesheet_id=p_timesheet_id;
  select * into v_fin from public.timesheets_financials row
  where row.timesheet_id=p_timesheet_id and row.is_current
  order by row.computed_at_utc desc nulls last,row.updated_at desc,row.id desc limit 1;
  if not found or v_timesheet.timesheet_id is null then
    return jsonb_build_object('ok',true,'component_count',0);
  end if;
  v_agency:=case
    when v_fin.paid_at_utc is not null or upper(coalesce(v_timesheet.status::text,''))='PAID'
      then 'PAID'
    when v_fin.locked_by_invoice_id is not null
      or upper(coalesce(v_timesheet.status::text,''))='INVOICED' then 'INVOICED'
    when v_fin.authorised_at_utc is not null or v_timesheet.authorised_at_server is not null
      or upper(coalesce(v_timesheet.status::text,'')) in ('AUTHORISED','AUTHORIZED')
      then 'AUTHORISED'
    else 'NOT_AUTHORISED' end;
  for v_component in
    select component.*
    from public.candidate_expense_components component
    where component.lifecycle_state not in (
      'MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED'
    )
      and private._candidate_expense_owned_timesheet_id_v1(
        component.workflow_id,component.owning_timesheet_id
      )=p_timesheet_id
    order by component.expense_component_id
    for update
  loop
    if v_component.agency_authorisation_state is distinct from v_agency
       or v_component.owning_timesheet_id is distinct from p_timesheet_id then
      v_before:=to_jsonb(v_component);
      update public.candidate_expense_components set
        component_generation=component_generation+1,
        owning_timesheet_id=p_timesheet_id,
        agency_authorisation_state=v_agency,
        updated_at_utc=p_now_utc
      where expense_component_id=v_component.expense_component_id
      returning * into v_component;
      insert into public.candidate_expense_component_events(
        expense_component_id,workflow_id,component_generation,event_type,actor_kind,
        before_state_json,after_state_json,idempotency_key,occurred_at_utc
      ) values (
        v_component.expense_component_id,v_component.workflow_id,
        v_component.component_generation,
        case when v_before->>'agency_authorisation_state' is not distinct from v_agency
          then 'OWNER_ROTATED'
          else case v_agency when 'PAID' then 'PAID' when 'INVOICED' then 'INVOICED'
            when 'AUTHORISED' then 'AUTHORISED' else 'AGENCY_PROTECTION_CLEARED' end end,
        'SYSTEM',v_before,to_jsonb(v_component),
        'financial-protection-sync:'||v_fin.id::text||':'
          ||v_component.expense_component_id::text||':'||v_agency||':'
          ||p_timesheet_id::text,p_now_utc
      ) on conflict(expense_component_id,idempotency_key) do nothing;
      v_count:=v_count+1;
    end if;
  end loop;
  return jsonb_build_object('ok',true,'timesheet_id',p_timesheet_id,
    'component_count',v_count);
end;
$function$;

-- [REPLACES] private._candidate_expense_summary_queue_v1(p_timesheet_id uuid, p_now_utc timestamp with time zone)  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private._candidate_expense_summary_queue_v1(p_timesheet_id uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_fin public.timesheets_financials%rowtype;
  v_is_daily boolean:=false;
  v_total numeric;
  v_has_summary boolean;
  v_totals jsonb;
  v_digest bytea;
  v_generation integer;
  v_refresh public.candidate_expense_summary_refreshes%rowtype;
  v_identity jsonb;
  v_evidence_counts jsonb;
  v_categories jsonb;
  v_cleanup_failures jsonb:='[]'::jsonb;
  v_cleanup_record jsonb;
begin
  if private._candidate_expense_source_family_v1(p_timesheet_id) then
    return jsonb_build_object('ok',true,'timesheet_id',p_timesheet_id,'summary_state','NOT_REQUIRED');
  end if;
  if p_timesheet_id is null then
    raise exception 'TIMESHEET_ID_REQUIRED' using errcode='22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('candidate-expense-summary|'||p_timesheet_id::text,0)
  );
  select financial.* into v_fin
  from public.timesheets_financials financial
  where financial.timesheet_id=p_timesheet_id and financial.is_current
  order by financial.computed_at_utc desc nulls last,
    financial.updated_at desc,financial.id desc
  limit 1 for update;
  if not found then
    return jsonb_build_object('ok',true,'timesheet_id',p_timesheet_id,
      'summary_state','NOT_REQUIRED');
  end if;
  select exists(
    select 1 from public.timesheets timesheet
    where timesheet.timesheet_id=p_timesheet_id
      and timesheet.sheet_scope='DAILY'::public.timesheet_scope_enum
  ) into v_is_daily;
  v_total:=case when v_is_daily then 0 else
    coalesce(v_fin.mileage_pay_ex_vat,0)
      +coalesce(v_fin.travel_pay_ex_vat,0)
      +coalesce(v_fin.accommodation_pay_ex_vat,0)
      +coalesce(v_fin.other_pay_ex_vat,0) end;
  select jsonb_build_object(
    'candidate_name',nullif(btrim(coalesce(candidate.display_name,
      concat_ws(' ',candidate.first_name,candidate.last_name))),''),
    'candidate_reference',candidate.tms_ref,
    'client_name',client.name,'client_reference',client.cli_ref,
    'contract_id',contract.id,'contract_role',contract.role,
    'contract_site',contract.display_site,
    'week_ending_date',v_timesheet.week_ending_date
  ) into v_identity
  from public.timesheets v_timesheet
  left join public.contracts contract on contract.id=v_timesheet.contract_id
  left join public.candidates candidate on candidate.id=v_fin.candidate_id
  left join public.clients client on client.id=v_fin.client_id
  where v_timesheet.timesheet_id=p_timesheet_id;
  select coalesce(jsonb_object_agg(category.expense_category,
    category.source_count+category.materialised_only_count
    order by category.expense_category),'{}'::jsonb)
  into v_evidence_counts
  from (
    select requested.expense_category,
      (select count(distinct coalesce(source.source_component_id,source.id))::integer
       from public.candidate_expense_components component
       join public.candidate_submission_components source
         on source.workflow_id=component.workflow_id
        and source.workflow_generation=component.workflow_generation
        and source.expense_category=component.expense_category
        and source.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
        and source.state not in ('SUPERSEDED','REJECTED','ABANDONED')
       where component.expense_category=requested.expense_category
         and component.lifecycle_state not in (
           'MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED'
         )
         and private._candidate_expense_owned_timesheet_id_v1(
           component.workflow_id,component.owning_timesheet_id
         )=p_timesheet_id) as source_count,
      (select count(distinct evidence.id)::integer
       from public.timesheet_evidence evidence
       where evidence.timesheet_id=p_timesheet_id
         and evidence.processing_state<>'SUPERSEDED'
         and evidence.document_role<>'EXPENSE_MILEAGE_APPROVAL_SUMMARY'
         and upper(coalesce(evidence.kind::text,''))=requested.expense_category
         and (evidence.candidate_component_id is null or not exists(
           select 1
           from public.candidate_expense_components active_component
           join public.candidate_submission_components source
             on source.workflow_id=active_component.workflow_id
            and source.workflow_generation=active_component.workflow_generation
            and source.expense_category=active_component.expense_category
            and source.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
            and source.state not in ('SUPERSEDED','REJECTED','ABANDONED')
           left join public.candidate_submission_components materialised_source
             on materialised_source.id=evidence.candidate_component_id
           where active_component.expense_category=requested.expense_category
             and active_component.lifecycle_state not in (
               'MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED'
             )
             and private._candidate_expense_owned_timesheet_id_v1(
               active_component.workflow_id,active_component.owning_timesheet_id
             )=p_timesheet_id
             and coalesce(source.source_component_id,source.id)
               =coalesce(materialised_source.source_component_id,
                 evidence.candidate_component_id)
         ))) as materialised_only_count
    from (values ('MILEAGE'),('TRAVEL'),('ACCOMMODATION'),('OTHER'))
      requested(expense_category)
  ) category;
  select coalesce(jsonb_agg(jsonb_build_object(
    'expense_category',category.expense_category,
    'amount',category.amount,
    'mileage_units',category.mileage_units,
    'supporting_evidence_count',coalesce(
      (v_evidence_counts->>category.expense_category)::integer,0
    )
  ) order by category.ordinal),'[]'::jsonb)
  into v_categories
  from (
    values
      (1,'MILEAGE',coalesce(v_fin.mileage_pay_ex_vat,0),coalesce(v_fin.mileage_units,0)),
      (2,'TRAVEL',coalesce(v_fin.travel_pay_ex_vat,0),0::numeric),
      (3,'ACCOMMODATION',coalesce(v_fin.accommodation_pay_ex_vat,0),0::numeric),
      (4,'OTHER',coalesce(v_fin.other_pay_ex_vat,0),0::numeric)
  ) category(ordinal,expense_category,amount,mileage_units)
  where not v_is_daily and (category.amount<>0 or category.mileage_units<>0);
  v_has_summary:=jsonb_array_length(v_categories)>0;
  v_totals:=jsonb_build_object(
    'identity',coalesce(v_identity,'{}'::jsonb),
    'evidence_counts',coalesce(v_evidence_counts,'{}'::jsonb),
    'categories',v_categories,
    'mileage_units',case when v_is_daily then 0 else coalesce(v_fin.mileage_units,0) end,
    'mileage_pay_ex_vat',case when v_is_daily then 0 else coalesce(v_fin.mileage_pay_ex_vat,0) end,
    'travel_pay_ex_vat',case when v_is_daily then 0 else coalesce(v_fin.travel_pay_ex_vat,0) end,
    'accommodation_pay_ex_vat',case when v_is_daily then 0 else coalesce(v_fin.accommodation_pay_ex_vat,0) end,
    'other_pay_ex_vat',case when v_is_daily then 0 else coalesce(v_fin.other_pay_ex_vat,0) end,
    'expenses_pay_ex_vat',case when v_is_daily then 0 else
      coalesce(v_fin.travel_pay_ex_vat,0)
        +coalesce(v_fin.accommodation_pay_ex_vat,0)
        +coalesce(v_fin.other_pay_ex_vat,0) end,
    'total_pay_ex_vat',v_total
  );
  v_digest:=extensions.digest(pg_catalog.convert_to(v_totals::text,'UTF8'),'sha256');

  select refresh.* into v_refresh
  from public.candidate_expense_summary_refreshes refresh
  where refresh.timesheet_id_snapshot=p_timesheet_id
    and refresh.state in ('PENDING','RENDERING','READY','REMOVED')
  order by refresh.summary_generation desc
  limit 1 for update;
  if found and v_refresh.totals_sha256=v_digest
     and ((not v_has_summary and v_refresh.state='REMOVED')
       or (v_has_summary and v_refresh.state in ('PENDING','RENDERING','READY'))) then
    return jsonb_build_object(
      'ok',true,'timesheet_id',p_timesheet_id,
      'refresh_id',v_refresh.refresh_id,
      'summary_generation',v_refresh.summary_generation,
      'summary_state',v_refresh.state,'totals',v_totals,
      'idempotent_replay',true
    );
  end if;

  update public.candidate_expense_summary_refreshes refresh set
    state='SUPERSEDED',completed_at_utc=p_now_utc,updated_at_utc=p_now_utc,
    -- Retain the exact in-flight claim identity on a superseded render.  Its
    -- late completion can then prove and durably retire the attempt-specific
    -- R2 object instead of orphaning it.  A merely PENDING row has no claim.
    claim_token=case when refresh.state='RENDERING' then refresh.claim_token end,
    claimed_at_utc=case when refresh.state='RENDERING' then refresh.claimed_at_utc end,
    lease_expires_at_utc=case when refresh.state='RENDERING'
      then refresh.lease_expires_at_utc end
  where refresh.timesheet_id_snapshot=p_timesheet_id
    and refresh.state in ('PENDING','RENDERING');

  select coalesce(max(refresh.summary_generation),0)+1 into v_generation
  from public.candidate_expense_summary_refreshes refresh
  where refresh.timesheet_id_snapshot=p_timesheet_id;
  insert into public.candidate_expense_summary_refreshes(
    timesheet_id,timesheet_id_snapshot,summary_generation,state,totals_json,totals_sha256,
    source_financials_id,idempotency_key,requested_at_utc,completed_at_utc,
    updated_at_utc
  ) values (
    p_timesheet_id,p_timesheet_id,v_generation,
    case when not v_has_summary then 'REMOVED' else 'PENDING' end,
    v_totals,v_digest,v_fin.id,
    'expense-summary:'||p_timesheet_id::text||':'||v_generation::text||':'||encode(v_digest,'hex'),
    p_now_utc,case when not v_has_summary then p_now_utc else null end,p_now_utc
  ) returning * into v_refresh;

  if not v_has_summary then
    select coalesce(jsonb_agg(jsonb_build_object(
      'r2_key',current_summary.storage_key,'attempt_count',1,
      'error','EXPENSE_SUMMARY_REMOVED'
    ) order by current_summary.storage_key),'[]'::jsonb)
    into v_cleanup_failures
    from (
      select distinct evidence.storage_key
      from public.timesheet_evidence evidence
      where evidence.timesheet_id=p_timesheet_id
        and evidence.document_role='EXPENSE_MILEAGE_APPROVAL_SUMMARY'
        and evidence.processing_state<>'SUPERSEDED'
        and nullif(btrim(coalesce(evidence.storage_key,'')),'') is not null
    ) current_summary;
    update public.timesheet_evidence evidence set processing_state='SUPERSEDED'
    where evidence.timesheet_id=p_timesheet_id
      and evidence.document_role='EXPENSE_MILEAGE_APPROVAL_SUMMARY'
      and evidence.processing_state<>'SUPERSEDED';
    if jsonb_array_length(v_cleanup_failures)>0 then
      v_cleanup_record:=public.timesheet_r2_cleanup_record_v1(
        'candidate-expense-summary-remove:'||v_refresh.refresh_id::text,
        p_timesheet_id,array[]::uuid[],v_cleanup_failures,null
      );
      if coalesce((v_cleanup_record->>'ok')::boolean,false) is not true
         or coalesce((v_cleanup_record->>'valid_distinct_keys')::integer,-1)
            is distinct from jsonb_array_length(v_cleanup_failures) then
        raise exception 'CANDIDATE_EXPENSE_SUMMARY_CLEANUP_NOT_DURABLE'
          using errcode='40001';
      end if;
    end if;
  end if;
  return jsonb_build_object(
    'ok',true,'timesheet_id',p_timesheet_id,
    'refresh_id',v_refresh.refresh_id,
    'summary_generation',v_refresh.summary_generation,
    'summary_state',v_refresh.state,'totals',v_totals,
    'idempotent_replay',false
  );
end;
$function$;

-- [REPLACES] private._timesheet_duplicate_expense_review_v1(p_timesheet_id uuid)  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private._timesheet_duplicate_expense_review_v1(p_timesheet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
  IF private._candidate_expense_source_family_v1(p_timesheet_id) THEN
    RETURN jsonb_build_object('required',false,'workflow_id',null,'categories','[]'::jsonb);
  END IF;
  RETURN (
with matched_workflow as (
    select workflow_row.id,workflow_row.issue_codes,workflow_row.updated_at_utc
    from public.candidate_submission_workflows workflow_row
    where p_timesheet_id is not null
      and (
        workflow_row.target_timesheet_id=p_timesheet_id
        or (workflow_row.workflow_kind<>'CONTRACT_EXPENSE'
          and workflow_row.anchor_timesheet_id=p_timesheet_id)
      )
      and workflow_row.state not in ('CREATED','CANCELLED','EXPIRED','SUPERSEDED')
      and workflow_row.issue_codes ? 'DUPLICATE_EXPENSE_REVIEW'
    order by
      case when workflow_row.target_timesheet_id=p_timesheet_id then 0 else 1 end,
      workflow_row.updated_at_utc desc,
      workflow_row.id desc
    limit 1
  ), stored_categories as (
    select distinct replace(issue_code.value,'DUPLICATE_EXPENSE_','') as category
    from matched_workflow
    cross join lateral jsonb_array_elements_text(matched_workflow.issue_codes) issue_code(value)
    where issue_code.value like 'DUPLICATE_EXPENSE_%'
      and issue_code.value<>'DUPLICATE_EXPENSE_REVIEW'
      and replace(issue_code.value,'DUPLICATE_EXPENSE_','')
            in ('MILEAGE','TRAVEL','ACCOMMODATION','OTHER')
  ), target_workflow as (
    select
      workflow_row.id,workflow_row.candidate_id,workflow_row.anchor_timesheet_id,
      workflow_row.target_timesheet_id,workflow_row.week_ending_date,
      workflow_row.worker_submitted_at_utc,contract_row.client_id
    from public.candidate_submission_workflows workflow_row
    join public.contracts contract_row on contract_row.id=workflow_row.contract_id
    where p_timesheet_id is not null
      and workflow_row.target_timesheet_id=p_timesheet_id
      and workflow_row.workflow_kind in ('CONTRACT_COMBINED','CONTRACT_EXPENSE')
      and workflow_row.state='FINALISED'
      and workflow_row.worker_submitted_at_utc is not null
      and not exists(select 1 from matched_workflow)
    order by workflow_row.updated_at_utc desc,workflow_row.id desc
    limit 1
  ), current_categories as (
    select distinct case when component.component_kind='MILEAGE_FORM' then 'MILEAGE'
      else upper(component.expense_category) end as category
    from target_workflow
    join public.candidate_submission_components component
      on component.workflow_id=target_workflow.id
    where component.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
      and component.state not in ('SUPERSEDED','REJECTED')
      and case when component.component_kind='MILEAGE_FORM' then 'MILEAGE'
        else upper(component.expense_category) end
          in ('MILEAGE','TRAVEL','ACCOMMODATION','OTHER')
    union
    select category.category
    from target_workflow
    join public.timesheets_financials current_financial
      on current_financial.timesheet_id=target_workflow.target_timesheet_id
     and current_financial.is_current=true
    cross join lateral (values
      ('MILEAGE',abs(coalesce(current_financial.mileage_units,0))
        +abs(coalesce(current_financial.mileage_pay_ex_vat,0))
        +abs(coalesce(current_financial.mileage_charge_ex_vat,0))),
      ('TRAVEL',abs(coalesce(current_financial.travel_pay_ex_vat,0))
        +abs(coalesce(current_financial.travel_charge_ex_vat,0))),
      ('ACCOMMODATION',abs(coalesce(current_financial.accommodation_pay_ex_vat,0))
        +abs(coalesce(current_financial.accommodation_charge_ex_vat,0))),
      ('OTHER',abs(coalesce(current_financial.other_pay_ex_vat,0))
        +abs(coalesce(current_financial.other_charge_ex_vat,0))
        +case when abs(coalesce(current_financial.expenses_pay_ex_vat,0))
                       +abs(coalesce(current_financial.expenses_charge_ex_vat,0))>0
                    and abs(coalesce(current_financial.travel_pay_ex_vat,0))
                       +abs(coalesce(current_financial.travel_charge_ex_vat,0))
                       +abs(coalesce(current_financial.accommodation_pay_ex_vat,0))
                       +abs(coalesce(current_financial.accommodation_charge_ex_vat,0))
                       +abs(coalesce(current_financial.other_pay_ex_vat,0))
                       +abs(coalesce(current_financial.other_charge_ex_vat,0))=0
          then 1 else 0 end)
    ) category(category,amount)
    where category.amount>0
  ), prior_categories as (
    select distinct case when component.component_kind='MILEAGE_FORM' then 'MILEAGE'
      else upper(component.expense_category) end as category
    from target_workflow
    join public.candidate_submission_workflows prior_workflow
      on prior_workflow.id<>target_workflow.id
     and prior_workflow.candidate_id=target_workflow.candidate_id
     and prior_workflow.week_ending_date=target_workflow.week_ending_date
     and prior_workflow.workflow_kind in ('CONTRACT_COMBINED','CONTRACT_EXPENSE')
     and prior_workflow.worker_submitted_at_utc is not null
     and prior_workflow.worker_submitted_at_utc<target_workflow.worker_submitted_at_utc
     and prior_workflow.state not in ('CREATED','WORKER_DRAFT','CANCELLED','EXPIRED','SUPERSEDED')
    join public.contracts prior_contract on prior_contract.id=prior_workflow.contract_id
     and prior_contract.client_id=target_workflow.client_id
    join public.candidate_submission_components component
      on component.workflow_id=prior_workflow.id
    where coalesce(prior_workflow.target_timesheet_id,prior_workflow.anchor_timesheet_id)
            is distinct from coalesce(target_workflow.target_timesheet_id,target_workflow.anchor_timesheet_id)
      and component.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
      and component.state not in ('SUPERSEDED','REJECTED')
      and case when component.component_kind='MILEAGE_FORM' then 'MILEAGE'
        else upper(component.expense_category) end
          in ('MILEAGE','TRAVEL','ACCOMMODATION','OTHER')
    union
    select category.category
    from target_workflow
    join public.timesheets prior_timesheet
      on prior_timesheet.is_current=true
     and prior_timesheet.archived_at_utc is null
     and prior_timesheet.timesheet_id is distinct from target_workflow.target_timesheet_id
     and prior_timesheet.timesheet_id is distinct from target_workflow.anchor_timesheet_id
     and prior_timesheet.week_ending_date=target_workflow.week_ending_date
    join public.timesheets_financials prior_financial
      on prior_financial.timesheet_id=prior_timesheet.timesheet_id
     and prior_financial.is_current=true
     and prior_financial.candidate_id=target_workflow.candidate_id
     and prior_financial.client_id=target_workflow.client_id
     and coalesce(prior_financial.computed_at_utc,prior_financial.created_at,prior_timesheet.created_at)
          <=target_workflow.worker_submitted_at_utc
    cross join lateral (values
      ('MILEAGE',abs(coalesce(prior_financial.mileage_units,0))
        +abs(coalesce(prior_financial.mileage_pay_ex_vat,0))
        +abs(coalesce(prior_financial.mileage_charge_ex_vat,0))),
      ('TRAVEL',abs(coalesce(prior_financial.travel_pay_ex_vat,0))
        +abs(coalesce(prior_financial.travel_charge_ex_vat,0))),
      ('ACCOMMODATION',abs(coalesce(prior_financial.accommodation_pay_ex_vat,0))
        +abs(coalesce(prior_financial.accommodation_charge_ex_vat,0))),
      ('OTHER',abs(coalesce(prior_financial.other_pay_ex_vat,0))
        +abs(coalesce(prior_financial.other_charge_ex_vat,0))
        +case when abs(coalesce(prior_financial.expenses_pay_ex_vat,0))
                       +abs(coalesce(prior_financial.expenses_charge_ex_vat,0))>0
                    and abs(coalesce(prior_financial.travel_pay_ex_vat,0))
                       +abs(coalesce(prior_financial.travel_charge_ex_vat,0))
                       +abs(coalesce(prior_financial.accommodation_pay_ex_vat,0))
                       +abs(coalesce(prior_financial.accommodation_charge_ex_vat,0))
                       +abs(coalesce(prior_financial.other_pay_ex_vat,0))
                       +abs(coalesce(prior_financial.other_charge_ex_vat,0))=0
          then 1 else 0 end)
    ) category(category,amount)
    where category.amount>0
  ), recovered_categories as (
    select current_categories.category
    from current_categories
    join prior_categories using(category)
  )
  select jsonb_build_object(
    'required',matched_workflow.id is not null
      or exists(select 1 from recovered_categories),
    'workflow_id',case when matched_workflow.id is not null then matched_workflow.id
      when exists(select 1 from recovered_categories) then target_workflow.id else null end,
    'categories',case when matched_workflow.id is not null then coalesce(
      (select jsonb_agg(stored_categories.category order by stored_categories.category)
       from stored_categories),'[]'::jsonb
    ) else coalesce(
      (select jsonb_agg(recovered_categories.category order by recovered_categories.category)
       from recovered_categories),'[]'::jsonb
    ) end
  )
  from (select 1) singleton
  left join matched_workflow on true
  left join target_workflow on true
  );
END;
$function$;

-- [REPLACES] private.weekly_source_first_authorisation_context_v1(p_timesheet_id uuid)  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private.weekly_source_first_authorisation_context_v1(p_timesheet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_identity jsonb;
  v_members uuid[];
  v_canonical uuid;
  v_family text;
  v_root public.timesheets%rowtype;
  v_candidate_id uuid;
  v_contract_candidate_id uuid;
  v_tsfin_owner_count integer;
  v_contract_week_id uuid;
  v_contract_week_count integer;
  v_signature_json jsonb;
  v_signature text;
  v_live public.weekly_source_root_authorisations%rowtype;
  v_live_count integer;
  v_family_count integer;
  v_live_elsewhere integer;
  v_max_generation integer;
begin
  if p_timesheet_id is null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','ROOT_ID_REQUIRED');
  end if;

  v_identity:=private.weekly_source_resolve_root_identity_v1(p_timesheet_id);
  if coalesce((v_identity->>'ok')::boolean,false) is not true then
    return v_identity||pg_catalog.jsonb_build_object('retryable',false);
  end if;

  v_family:=v_identity->>'family_booking_id';
  v_canonical:=(v_identity->>'canonical_timesheet_id')::uuid;
  select pg_catalog.array_agg(member_element.value::uuid)
    into v_members
  from pg_catalog.jsonb_array_elements_text(v_identity->'member_timesheet_ids')
    as member_element(value);

  select * into v_root from public.timesheets where timesheet_id=v_canonical;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','CANONICAL_ROW_MISSING');
  end if;

  -- The Candidate the serial gate is pinned to.  contracts.candidate_id is
  -- nullable, so a null or disagreeing owner fails closed rather than
  -- serialising the withdrawal under the wrong Candidate key.
  select contract_row.candidate_id
    into v_contract_candidate_id
  from public.contracts as contract_row
  where contract_row.id=v_root.contract_id;

  -- The current TSFIN owner, read as a set so a second current row owned by
  -- another Candidate is a conflict rather than an arbitrary pick.  The
  -- installed invalidator refuses on exactly that shape
  -- (PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH), so refusing here
  -- keeps the withdrawal from writing anything at all.
  select pg_catalog.count(distinct financial_row.candidate_id)::integer,
         pg_catalog.min(financial_row.candidate_id::text)::uuid
    into v_tsfin_owner_count, v_candidate_id
  from public.timesheets_financials as financial_row
  where financial_row.timesheet_id=v_canonical
    and financial_row.is_current=true
    and financial_row.candidate_id is not null;

  if v_contract_candidate_id is null
     or v_tsfin_owner_count>1
     or (v_candidate_id is not null and v_candidate_id is distinct from v_contract_candidate_id) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','CANDIDATE_UNRESOLVED',
      'family_booking_id',v_family,'canonical_timesheet_id',v_canonical);
  end if;
  v_candidate_id:=v_contract_candidate_id;

  -- The Contract Week the signature helper is given.  More than one week row
  -- pointing at one physical Timesheet is not a shape the installed owners
  -- produce, so the cardinality is checked rather than assumed.
  select pg_catalog.count(*)::integer,
         pg_catalog.min(contract_week_row.id::text)::uuid
    into v_contract_week_count, v_contract_week_id
  from public.contract_weeks as contract_week_row
  where contract_week_row.timesheet_id=v_canonical;
  if v_contract_week_count>1 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason','CONTRACT_WEEK_CARDINALITY',
      'family_booking_id',v_family,'canonical_timesheet_id',v_canonical);
  end if;

  v_signature_json:=public.timesheet_lifecycle_guard_signature_v1(
    v_canonical,v_contract_week_id,false);
  v_signature:=nullif(pg_catalog.btrim(coalesce(
    v_signature_json->>'backend_row_signature',
    v_signature_json->>'row_signature','')),'');

  -- Live and historical root-authorisation generations for the family.
  select pg_catalog.count(*)::integer
    into v_family_count
  from public.weekly_source_root_authorisations as authorisation_row
  where authorisation_row.root_timesheet_id=any(v_members);

  select pg_catalog.count(*)::integer
    into v_live_count
  from public.weekly_source_root_authorisations as authorisation_row
  where authorisation_row.root_timesheet_id=any(v_members)
    and authorisation_row.withdrawn_at_utc is null;

  select pg_catalog.count(*)::integer
    into v_live_elsewhere
  from public.weekly_source_root_authorisations as authorisation_row
  where authorisation_row.root_timesheet_id=any(v_members)
    and authorisation_row.root_timesheet_id is distinct from v_canonical
    and authorisation_row.withdrawn_at_utc is null;

  select coalesce(pg_catalog.max(authorisation_row.authorisation_generation),0)
    into v_max_generation
  from public.weekly_source_root_authorisations as authorisation_row
  where authorisation_row.root_timesheet_id=v_canonical;

  if v_live_count>1 or v_live_elsewhere>0 then
    -- A live generation on a historical member means the authorised root was
    -- rotated after first authorisation: proof/34 section 6 integrity failure.
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
      'reason',case when v_live_elsewhere>0
                    then 'LIVE_AUTHORISATION_NOT_ON_CANONICAL_ROW'
                    else 'LIVE_AUTHORISATION_CARDINALITY' end,
      'family_booking_id',v_family,'canonical_timesheet_id',v_canonical);
  end if;

  select * into v_live
  from public.weekly_source_root_authorisations as authorisation_row
  where authorisation_row.root_timesheet_id=v_canonical
    and authorisation_row.withdrawn_at_utc is null;

  return pg_catalog.jsonb_build_object(
    'ok',true,
    'timesheet_id',p_timesheet_id,
    'family_booking_id',v_family,
    'canonical_timesheet_id',v_canonical,
    'canonical_version',(v_identity->>'canonical_version')::integer,
    'requested_version',(v_identity->>'requested_version')::integer,
    'requested_is_canonical',coalesce((v_identity->>'requested_is_canonical')::boolean,false),
    'family_is_current',coalesce((v_identity->>'family_is_current')::boolean,false),
    'member_timesheet_ids',pg_catalog.to_jsonb(v_members),
    'candidate_id',v_candidate_id,
    'contract_id',v_root.contract_id,
    'contract_week_id',v_contract_week_id,
    'current_row_signature',v_signature,
    'root',pg_catalog.jsonb_build_object(
      'timesheet_id',v_root.timesheet_id,
      'booking_id',v_root.booking_id,
      'version',v_root.version,
      'is_current',v_root.is_current,
      'authorised_at_server',v_root.authorised_at_server,
      'archived_at_utc',v_root.archived_at_utc),
    'live_authorisation_count',v_live_count,
    'family_authorisation_count',v_family_count,
    'max_generation',v_max_generation,
    'authorisation',case when v_live.id is null then null else pg_catalog.jsonb_build_object(
      'id',v_live.id,
      'root_timesheet_id',v_live.root_timesheet_id,
      'family_booking_id',v_live.family_booking_id,
      'timesheet_version',v_live.timesheet_version,
      'authorisation_generation',v_live.authorisation_generation,
      'authorised_row_signature',v_live.authorised_row_signature,
      'current_entitlement_head_id',v_live.current_entitlement_head_id,
      'authorised_by_user_id',v_live.authorised_by_user_id,
      'authorised_at_utc',v_live.authorised_at_utc,
      -- ROUND 5 Part E: the five-field signature binding, and the digest
      -- REBUILT from the row's own bindings so W9 can compare the two.  A row
      -- written before the binding existed carries a null stored digest and is
      -- refused by name; it never passes by accident.
      'agency_id',v_live.agency_id,
      'evidence_codec',v_live.bpay_evidence_codec_v1,
      'protected_evidence_reference',v_live.bpay_evidence_reference_v1,
      'protected_decision_hashes',case when v_live.bpay_evidence_codec_v1=1 then pg_catalog.to_jsonb(coalesce(v_live.protected_decision_hashes,array[]::text[])) else null end,
      'decision_digest',case when v_live.decision_digest is null then null
                        else pg_catalog.encode(v_live.decision_digest,'hex') end,
      'decision_digest_rebuilt',pg_catalog.encode(
        private.weekly_source_publication_request_digest_v1(
          private.bpay_protected_reference_authorisation_signature_v1(
            v_live.agency_id,v_live.root_timesheet_id,v_live.family_booking_id,
            v_live.timesheet_version,v_live.authorisation_generation,
            v_live.authorised_row_signature,
            case when v_live.bpay_evidence_codec_v1=1 then coalesce(v_live.protected_decision_hashes,array[]::text[]) else v_live.protected_decision_hashes end,
            v_live.bpay_evidence_codec_v1,v_live.bpay_evidence_reference_v1)),
        'hex')) end
  );
end;
$function$;

-- [REPLACES] private.weekly_source_first_authorise_core_v1(p_timesheet_id uuid, p_expected_row_signature text, p_actor_user_id uuid, p_lock_result jsonb)  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION private.weekly_source_first_authorise_core_v1(p_timesheet_id uuid, p_expected_row_signature text, p_actor_user_id uuid, p_lock_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_family jsonb;

  v_elsewhere uuid;
  v_actor public.tms_users%rowtype;
  v_authorise jsonb;
  v_root public.timesheets%rowtype;
  v_contract_week_id uuid;
  v_signature text;
  v_signature_json jsonb;
  v_generation integer;
  v_agency_id uuid;
  v_protected_hashes text[];
  v_evidence_reference jsonb;
  v_decision_digest bytea;
  v_id uuid;
begin
  if p_timesheet_id is null or p_actor_user_id is null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_FIRST_AUTHORISE_REQUEST_INVALID',
      'retryable',false,'reason','TIMESHEET_AND_ACTOR_REQUIRED');
  end if;

  select * into v_actor from public.tms_users where id=p_actor_user_id;
  if not found or not coalesce(v_actor.is_active,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_FIRST_AUTHORISE_ACTOR_INVALID',
      'retryable',false,'reason','ACTOR_NOT_FOUND_OR_INACTIVE');
  end if;

  -- proof/34 section 5 steps 2 and 3: the lock result is the proof that the
  -- deadlock-free lock set is held and the only source of the canonical answer.
  if coalesce((p_lock_result->>'ok')::boolean,false) is not true
     or coalesce(p_lock_result->>'gate','')<>'GRANTED' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_FIRST_AUTHORISE_LOCK_RESULT_INVALID',
      'retryable',false,'reason','LOCK_RESULT_NOT_GRANTED');
  end if;

  select family_element.value
    into v_family
  from pg_catalog.jsonb_array_elements(coalesce(p_lock_result->'families','[]'::jsonb))
    as family_element(value)
  where (family_element.value->>'requested_timesheet_id')::uuid=p_timesheet_id;

  if v_family is null
     or coalesce((v_family->>'requested_is_canonical')::boolean,false) is not true
     or coalesce((v_family->>'family_is_current')::boolean,false) is not true
     or (v_family->>'canonical_timesheet_id')::uuid is distinct from p_timesheet_id then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION',
      'retryable',false,'timesheet_id',p_timesheet_id,
      'canonical_timesheet_id',v_family->>'canonical_timesheet_id');
  end if;

  -- The outer owner still holds its accepted family locks. This core
  -- addresses the live financial authorisation directly by frozen work key;
  -- it never treats obsolete Timesheet hours as current entitlement.
  -- WP-07b finding F2: a live generation anywhere ELSE in the family means the
  -- authorised root was rotated after its first authorisation.  proof/34
  -- section 6: "the operation stops with WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE,
  -- no financial change is made, and Office review is required."  Refused
  -- before the ordinary Authorise owner is called, so nothing is written.
  select live_row.root_timesheet_id
    into v_elsewhere
  from public.weekly_source_root_authorisations as live_row
  where live_row.family_booking_id=v_family->>'family_booking_id'
    and live_row.root_timesheet_id is distinct from p_timesheet_id
    and live_row.withdrawn_at_utc is null
  limit 1;
  if v_elsewhere is not null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
      'retryable',false,'reason','LIVE_AUTHORISATION_NOT_ON_CANONICAL_ROW',
      'timesheet_id',p_timesheet_id,
      'live_authorisation_root_timesheet_id',v_elsewhere,
      'family_booking_id',v_family->>'family_booking_id');
  end if;

  -- A live generation on the requested row means the root is already an
  -- authorised managed root; re-authorisation is only ever the path after a
  -- withdrawal.
  if exists (select 1 from public.weekly_source_root_authorisations as live_row
             where live_row.root_timesheet_id=p_timesheet_id
               and live_row.withdrawn_at_utc is null) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_ROOT_ALREADY_AUTHORISED',
      'retryable',false,'timesheet_id',p_timesheet_id);
  end if;

  -- The Office projection has always described this as a first-authorisation
  -- hold. Enforce it in the command while the canonical family locks are held,
  -- using the Timesheet's work week rather than the source cutoff period.
  select * into v_root from public.timesheets where timesheet_id=p_timesheet_id;
  if not found then
    return pg_catalog.jsonb_build_object('ok',false,
      'code','WEEKLY_SOURCE_FIRST_AUTHORISE_TIMESHEET_MISSING','retryable',false);
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_QUERY_FAMILY:'||v_root.contract_id::text||':'||v_root.week_ending_date::text,0));
  if exists (
    select 1 from private.weekly_source_manual_reviews manual_review
    where manual_review.contract_id=v_root.contract_id
      and manual_review.work_date between v_root.week_ending_date-6 and v_root.week_ending_date
      and manual_review.state='OPEN'
  ) then
    return pg_catalog.jsonb_build_object('ok',false,
      'code','WEEKLY_SOURCE_FIRST_AUTHORISE_QUERY_OPEN','retryable',false,
      'reason','RESOLVE_MANUAL_QUERY');
  end if;
  if exists (
    select 1 from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    where incident.state='OPEN'
      and comparison.contract_id=v_root.contract_id
      and work_event.work_date between v_root.week_ending_date-6 and v_root.week_ending_date
      and not exists (
        select 1 from public.weekly_exceptional_pay_family_events protected_event
        join public.weekly_exceptional_pay_target_families protected_family
          on protected_family.id=protected_event.family_id
        where protected_family.root_family_booking_id=v_root.booking_id
          and protected_event.durable_work_event_id=incident.work_event_id
          and protected_event.state='WAIT'
          and protected_event.event_sequence=(
            select max(latest.event_sequence)
            from public.weekly_exceptional_pay_family_events latest
            where latest.family_id=protected_event.family_id
              and latest.durable_work_event_id=protected_event.durable_work_event_id))
  ) then
    return pg_catalog.jsonb_build_object('ok',false,
      'code','WEEKLY_SOURCE_FIRST_AUTHORISE_QUERY_OPEN','retryable',false,
      'reason','RESOLVE_OPEN_HOURS_QUERY');
  end if;

  -- The UNCHANGED ordinary Authorise owner, exactly once, through its current
  -- contract.  No timestamp is passed: the owner keeps its own default.
  v_evidence_reference:=private.bpay_protected_reference_for_root_v1(p_timesheet_id);

  v_authorise:=public.timesheet_authorise_generic_atomic(
    p_timesheet_id=>p_timesheet_id,
    p_expected_timesheet_id=>p_timesheet_id,
    p_actor_user_id=>p_actor_user_id,
    p_expected_row_signature=>nullif(pg_catalog.btrim(coalesce(p_expected_row_signature,'')),''));

  if coalesce((v_authorise->>'ok')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_FIRST_AUTHORISE_OWNER_REFUSED'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_FIRST_AUTHORISE_OWNER_REFUSED',
              'timesheet_id',p_timesheet_id,
              'authorise_result',v_authorise)::text;
  end if;

  select * into v_root from public.timesheets where timesheet_id=p_timesheet_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE',
              'reason','CANONICAL_ROW_MISSING_AFTER_AUTHORISE',
              'timesheet_id',p_timesheet_id)::text;
  end if;

  -- proof/34 section 4: the row signature AT authorisation.  Read from the
  -- owner's own return where it gives one, else recomputed; blank fails closed.
  v_signature:=nullif(pg_catalog.btrim(coalesce(
    v_authorise->>'backend_row_signature',v_authorise->>'row_signature','')),'');
  if v_signature is null then
    select contract_week_row.id into v_contract_week_id
    from public.contract_weeks as contract_week_row
    where contract_week_row.timesheet_id=p_timesheet_id;
    v_signature_json:=public.timesheet_lifecycle_guard_signature_v1(
      p_timesheet_id,v_contract_week_id,false);
    v_signature:=nullif(pg_catalog.btrim(coalesce(
      v_signature_json->>'backend_row_signature',
      v_signature_json->>'row_signature','')),'');
  end if;
  if v_signature is null or pg_catalog.char_length(v_signature)>512 then
    raise exception 'WEEKLY_SOURCE_ROOT_SIGNATURE_UNAVAILABLE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_ROOT_SIGNATURE_UNAVAILABLE',
              'timesheet_id',p_timesheet_id)::text;
  end if;

  select coalesce(pg_catalog.max(prior_row.authorisation_generation),0)+1
    into v_generation
  from public.weekly_source_root_authorisations as prior_row
  where prior_row.root_timesheet_id=p_timesheet_id;

  -- ROUND 5 Part E, the rotation/signature ruling: the authorisation row binds
  -- all five required fields, and the canonical digest of them is stored on the
  -- row so that a later reader can prove the row is the one that was written
  -- rather than trusting the columns individually.  Bound over the WHOLE
  -- family: the protected decisions and the agency evidence belong to the
  -- family, not to whichever physical row is current.
  SELECT agency_id INTO v_agency_id
  FROM private.bpay_protected_family_for_current_v1(p_timesheet_id);
  v_protected_hashes:=NULL; -- V2 uses the frozen reference; never pretend this is a V1 empty set.
  v_decision_digest:=private.weekly_source_publication_request_digest_v1(
    private.bpay_protected_reference_authorisation_signature_v1(
      v_agency_id,p_timesheet_id,v_root.booking_id,v_root.version,v_generation,
      v_signature,v_protected_hashes,2::smallint,v_evidence_reference));

  insert into public.weekly_source_root_authorisations(
    root_timesheet_id,family_booking_id,timesheet_version,authorisation_generation,
    authorised_row_signature,current_entitlement_head_id,authorised_by_user_id,
    agency_id,protected_decision_hashes,decision_digest,bpay_evidence_codec_v1,bpay_evidence_reference_v1
  ) values (
    p_timesheet_id,v_root.booking_id,v_root.version,v_generation,
    v_signature,null,p_actor_user_id,
    v_agency_id,v_protected_hashes,v_decision_digest,2,v_evidence_reference
  ) returning id into v_id;

  return pg_catalog.jsonb_build_object(
    'ok',true,
    'timesheet_id',p_timesheet_id,
    'root_authorisation_id',v_id,
    'authorisation_generation',v_generation,
    'family_booking_id',v_root.booking_id,
    'timesheet_version',v_root.version,
    'authorised_row_signature',v_signature,
    'agency_id',v_agency_id,
    'decision_digest',pg_catalog.encode(v_decision_digest,'hex'),
    'authorise_result',pg_catalog.jsonb_build_object(
      'ok',true,
      'operation',v_authorise->>'operation',
      'timesheet_id',v_authorise->>'timesheet_id',
      'contract_week_id',v_authorise->>'contract_week_id',
      'processing_status',v_authorise->>'processing_status'));
end;
$function$;

-- [REPLACES] private.weekly_source_ordinary_authorisation_guard_v1(p_timesheet_id uuid, p_booking_id text)  winner piece A11_S02
CREATE OR REPLACE FUNCTION private.weekly_source_ordinary_authorisation_guard_v1(p_timesheet_id uuid, p_booking_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE current_id uuid;
 n_current integer; n_live_current integer; other_live boolean;
 actual_booking text; bound boolean:=false; relevant boolean;
 ok boolean:=false; managed boolean:=false; contradictory boolean:=false;
 authorised boolean; refuse boolean; reason text; basis text;
 result_family text; result_current uuid;
BEGIN
 IF p_timesheet_id IS NULL THEN
  RETURN jsonb_build_object('refuse',true,'refusal_basis','WEEKLY_SOURCE_MANAGED_ROOT',
   'reason','ROOT_ID_REQUIRED','timesheet_id',null,'managed',true,'ok',false,
   'weekly_source_bound',true,'authorisation_record_without_authorised_timesheet',false);
 END IF;
 SELECT booking_id INTO actual_booking FROM public.timesheets WHERE timesheet_id=p_timesheet_id;
 relevant:=FOUND;
 IF NOT relevant THEN
  relevant:=EXISTS(SELECT 1 FROM public.weekly_source_row_timesheet_lineages WHERE timesheet_id=p_timesheet_id)
    OR EXISTS(SELECT 1 FROM public.weekly_source_root_authorisations WHERE root_timesheet_id=p_timesheet_id)
    OR EXISTS(SELECT 1 FROM public.weekly_exceptional_pay_target_families WHERE root_timesheet_id=p_timesheet_id);
  IF relevant THEN reason:='BOOKING_IDENTITY_MISSING';bound:=true;managed:=true;
  ELSE reason:='ROOT_NOT_FOUND'; END IF;
 ELSE
  PERFORM private.bpay_source_family_try_lock_v1(actual_booking);
  IF p_booking_id IS DISTINCT FROM actual_booking THEN
   PERFORM private.bpay_source_family_try_lock_v1(p_booking_id);
  END IF;
  -- S-02: ordinary rotations take no family lock; decide under native share locks on the requested row
  -- (already row-locked when called from the authorisation trigger) and on the family's current row.
  PERFORM private.bpay_source_row_gate_v1(p_timesheet_id,false);
  PERFORM private.bpay_source_family_current_gate_v1(actual_booking);
  IF (SELECT t.booking_id FROM public.timesheets t WHERE t.timesheet_id=p_timesheet_id) IS DISTINCT FROM actual_booking THEN
   RAISE EXCEPTION 'BPAY_SOURCE_FAMILY_BUSY' USING ERRCODE='55P03';
  END IF;
  -- Stored lineage family is enforced against its original physical identity;
  -- no expansion of all Timesheet versions is needed to establish binding.
  bound:=EXISTS(SELECT 1 FROM public.weekly_source_row_timesheet_lineages l
                WHERE l.timesheet_id=p_timesheet_id)
    OR (btrim(actual_booking)<>'' AND
       (EXISTS(SELECT 1 FROM public.weekly_source_row_timesheet_lineages l
                 WHERE btrim(l.family_booking_id)=btrim(actual_booking))
        OR EXISTS(SELECT 1 FROM public.weekly_exceptional_pay_target_families f
                 WHERE btrim(f.root_family_booking_id)=btrim(actual_booking))));
  IF actual_booking IS NULL OR btrim(actual_booking)='' THEN
   reason:='BOOKING_IDENTITY_MISSING'; managed:=true;
  ELSE
   IF NOT EXISTS(SELECT 1 FROM private.bpay_clock_rows_v1 r
     JOIN private.bpay_clock_families_v1 f ON f.id=r.family_id
     WHERE r.timesheet_id=p_timesheet_id AND f.booking_id=actual_booking) THEN
    RAISE EXCEPTION 'BPAY_SOURCE_DIRECTORY_NOT_READY' USING ERRCODE='55000';
   END IF;
   IF EXISTS(SELECT 1 FROM private.bpay_clock_families_v1 f
      WHERE btrim(f.booking_id)=btrim(actual_booking) AND f.booking_id<>actual_booking) THEN
    reason:='BOOKING_REFERENCE_CANONICAL_COLLISION'; managed:=true;
   ELSE
    SELECT count(*),min(t.timesheet_id::text)::uuid INTO n_current,current_id
    FROM (SELECT timesheet_id FROM public.timesheets
          WHERE booking_id=actual_booking AND is_current LIMIT 2) t;
    IF n_current<>1 THEN
     reason:=CASE WHEN n_current=0 THEN 'CANONICAL_AMBIGUOUS' ELSE 'CURRENT_ROW_CARDINALITY' END;
     managed:=true;
    ELSE
     -- Only live authority influences ordinary authorisation. Withdrawn
     -- records are immutable history, not rows that this operation must lock.
     PERFORM 1 FROM public.weekly_source_root_authorisations a
      WHERE a.family_booking_id=actual_booking AND a.withdrawn_at_utc IS NULL
      LIMIT 2 FOR UPDATE;
     SELECT count(*) INTO n_live_current FROM
       (SELECT 1 FROM public.weekly_source_root_authorisations a
        WHERE a.root_timesheet_id=current_id AND a.withdrawn_at_utc IS NULL LIMIT 2) a;
     other_live:=EXISTS(SELECT 1 FROM public.weekly_source_root_authorisations a
       WHERE a.family_booking_id=actual_booking AND a.withdrawn_at_utc IS NULL
       AND a.root_timesheet_id<>current_id);
     IF n_live_current>1 THEN
      reason:='ROOT_AUTHORISATION_CARDINALITY'; managed:=true;bound:=true;
      result_family:=actual_booking;result_current:=current_id;
     ELSIF other_live THEN
      reason:='AUTHORISED_ROOT_NOT_CANONICAL'; managed:=true;bound:=true;
      result_family:=actual_booking;result_current:=current_id;
     ELSE
      authorised:=EXISTS(SELECT 1 FROM public.timesheets t
                    WHERE t.timesheet_id=current_id AND t.authorised_at_server IS NOT NULL)
        OR EXISTS(SELECT 1 FROM public.timesheets_financials f
                    WHERE f.timesheet_id=current_id AND f.is_current AND f.authorised_at_utc IS NOT NULL)
        OR EXISTS(SELECT 1 FROM public.contract_weeks w
                    WHERE w.timesheet_id=current_id AND upper(btrim(w.status::text))='AUTHORISED');
      managed:=n_live_current=1 AND authorised;
      contradictory:=n_live_current=1 AND NOT authorised;
      ok:=true;result_family:=actual_booking;result_current:=current_id;
     END IF;
    END IF;
   END IF;
  END IF;
 END IF;
 refuse:=(managed AND (ok OR bound)) OR contradictory;
 basis:=CASE WHEN reason IN ('FAMILY_SPLIT_BY_WHITESPACE','BOOKING_REFERENCE_CANONICAL_COLLISION')
          THEN 'BOOKING_REFERENCE_CANONICAL_COLLISION'
        WHEN managed AND ok THEN 'WEEKLY_SOURCE_MANAGED_ROOT'
        WHEN managed THEN 'WEEKLY_SOURCE_BOUND_OR_PROTECTED_ROOT_UNRESOLVABLE'
        WHEN contradictory THEN 'AUTHORISATION_RECORD_WITHOUT_AUTHORISED_TIMESHEET'
        ELSE 'WEEKLY_SOURCE_MANAGED_ROOT' END;
 RETURN jsonb_build_object('refuse',refuse,'refusal_basis',CASE WHEN refuse THEN basis ELSE NULL END,
  'reason',reason,'timesheet_id',p_timesheet_id,'canonical_timesheet_id',result_current,
  'family_booking_id',result_family,'managed',managed,'ok',ok,'weekly_source_bound',bound,
  'authorisation_record_without_authorised_timesheet',contradictory);
END; $function$;

-- [REPLACES] public.pay_workbench_contract_client_dirty_fanout_chunk(p_job_id uuid, p_cursor_json jsonb, p_limit integer)  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION public.pay_workbench_contract_client_dirty_fanout_chunk(p_job_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  -- v5.2: the former function-level configuration clause that emptied the custom setting
  -- cloudtms.banking_pay_inherited_scope_generation is replaced by an explicit save / reset /
  -- restore of the same transaction-local setting, because a non-superuser release owner cannot
  -- CREATE a function whose configuration names an unregistered custom parameter (PostgreSQL 15+,
  -- "permission denied to set parameter"). Behaviour is unchanged: the body starts
  -- with the setting empty, and every normal return restores the caller's value so the
  -- inherited scope generation never leaks past this call; an error unwinds the setting
  -- through the enclosing (sub)transaction abort exactly as it did with the SET clause.
  v_saved_inherited_scope_generation text :=
    pg_catalog.current_setting('cloudtms.banking_pay_inherited_scope_generation', true);
  v_now timestamptz := now();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_payload_json jsonb := '{}'::jsonb;
  v_cursor_json jsonb := '{}'::jsonb;
  v_scope_kind text := '';
  v_scope_id_text text := NULL::text;
  v_scope_id uuid := NULL::uuid;
  v_specific_scope_id_text text := NULL::text;
  v_specific_scope_id uuid := NULL::uuid;
  v_payload_candidate_id_text text := NULL::text;
  v_payload_candidate_id uuid := NULL::uuid;
  v_payload_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_payload_candidate_value jsonb := NULL::jsonb;
  v_payload_candidate_value_text text := NULL::text;
  v_payload_candidate_index integer := 0;
  v_cursor_candidate_id_text text := NULL::text;
  v_cursor_candidate_id uuid := NULL::uuid;
  v_reason text := NULL::text;
  v_trigger_table text := NULL::text;
  v_trigger_op text := NULL::text;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_ids_json jsonb := '[]'::jsonb;
  v_candidate_count integer := 0;
  v_has_more boolean := false;
  v_last_candidate_id uuid := NULL::uuid;
  v_next_cursor_json jsonb := NULL::jsonb;
  v_affected_scope_count integer := 0;
  v_affected_session_count integer := 0;
  v_jobs_queued_or_reused integer := 0;
  v_source_rows_marked_dirty_count integer := 0;
  v_gate_candidate_id uuid := NULL::uuid;
  v_gate_result jsonb := '{}'::jsonb;
  v_gate_allowed_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_gate_blocked boolean := false;
  v_gate_blocked_candidate_id uuid := NULL::uuid;
  v_gate_last_allowed_candidate_id uuid := NULL::uuid;
  v_gate_allowed_count integer := 0;
  v_invalidation_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_invalidation_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_scope_change_tx_token uuid := NULL::uuid;
  v_scope_invalidation_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM pg_catalog.set_config('cloudtms.banking_pay_inherited_scope_generation', '', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_ID_REQUIRED'
            )::text;
  END IF;

  SELECT fanout_job.*
  INTO v_job_row
  FROM public.banking_pay_workbench_jobs AS fanout_job
  WHERE fanout_job.id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_FOUND',
              'job_id', p_job_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_job_row.job_type, ''))) <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_TYPE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_TYPE_INVALID',
              'job_id', v_job_row.id::text,
              'job_type', v_job_row.job_type
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_job_row.status, ''))) <> 'RUNNING' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_RUNNING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_RUNNING',
              'job_id', v_job_row.id::text,
              'status', v_job_row.status
            )::text;
  END IF;

  IF v_job_row.scope_change_generation IS NOT NULL THEN
    PERFORM set_config(
      'cloudtms.banking_pay_inherited_scope_generation',
      v_job_row.scope_change_generation::text,
      true
    );
  END IF;

  v_payload_json := CASE
    WHEN jsonb_typeof(COALESCE(v_job_row.payload_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(v_job_row.payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_cursor_json := CASE
    WHEN p_cursor_json IS NOT NULL
         AND jsonb_typeof(p_cursor_json) = 'object'
      THEN p_cursor_json
    WHEN jsonb_typeof(v_payload_json->'cursor_json') = 'object'
      THEN v_payload_json->'cursor_json'
    WHEN jsonb_typeof(v_payload_json->'cursor') = 'object'
      THEN v_payload_json->'cursor'
    ELSE '{}'::jsonb
  END;

  v_scope_kind := UPPER(BTRIM(COALESCE(v_payload_json->>'scope_kind', '')));

  IF v_scope_kind NOT IN ('CONTRACT', 'CLIENT', 'UMBRELLA') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_KIND_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_KIND_INVALID',
              'job_id', v_job_row.id::text,
              'scope_kind', v_scope_kind
            )::text;
  END IF;

  v_scope_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload_json->>'scope_id', '')), ''),
    CASE
      WHEN v_scope_kind = 'CONTRACT'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'contract_id', '')), '')
      WHEN v_scope_kind = 'CLIENT'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'client_id', '')), '')
      WHEN v_scope_kind = 'UMBRELLA'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'umbrella_id', '')), '')
      ELSE NULL::text
    END
  );

  IF COALESCE(v_scope_id_text, '')
     !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_ID_INVALID',
              'job_id', v_job_row.id::text,
              'scope_kind', v_scope_kind,
              'scope_id', v_scope_id_text
            )::text;
  END IF;

  v_scope_id := v_scope_id_text::uuid;

  v_specific_scope_id_text := CASE
    WHEN v_scope_kind = 'CONTRACT'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'contract_id', '')), '')
    WHEN v_scope_kind = 'CLIENT'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'client_id', '')), '')
    WHEN v_scope_kind = 'UMBRELLA'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'umbrella_id', '')), '')
    ELSE NULL::text
  END;

  IF v_specific_scope_id_text IS NOT NULL THEN
    IF v_specific_scope_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SPECIFIC_SCOPE_ID_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SPECIFIC_SCOPE_ID_INVALID',
                'job_id', v_job_row.id::text,
                'scope_kind', v_scope_kind,
                'scope_id', v_scope_id::text,
                'specific_scope_id', v_specific_scope_id_text
              )::text;
    END IF;

    v_specific_scope_id := v_specific_scope_id_text::uuid;

    IF v_specific_scope_id IS DISTINCT FROM v_scope_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_PAYLOAD_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_PAYLOAD_CONFLICT',
                'job_id', v_job_row.id::text,
                'scope_kind', v_scope_kind,
                'scope_id', v_scope_id::text,
                'specific_scope_id', v_specific_scope_id::text
              )::text;
    END IF;
  END IF;

  IF v_payload_json ? 'candidate_ids' THEN
    IF jsonb_typeof(v_payload_json->'candidate_ids') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID',
                'job_id', v_job_row.id::text,
                'candidate_ids', v_payload_json->'candidate_ids'
              )::text;
    END IF;

    v_payload_candidate_index := 0;

    FOR v_payload_candidate_value IN
      SELECT payload_candidate.value
      FROM jsonb_array_elements(v_payload_json->'candidate_ids') AS payload_candidate(value)
    LOOP
      v_payload_candidate_index := v_payload_candidate_index + 1;
      v_payload_candidate_value_text := CASE
        WHEN jsonb_typeof(v_payload_candidate_value) = 'string'
          THEN NULLIF(BTRIM(v_payload_candidate_value #>> '{}'), '')
        ELSE NULL::text
      END;

      IF COALESCE(v_payload_candidate_value_text, '')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID',
                  'job_id', v_job_row.id::text,
                  'candidate_index', v_payload_candidate_index,
                  'candidate_value', v_payload_candidate_value
                )::text;
      END IF;

      v_payload_candidate_ids := array_append(
        v_payload_candidate_ids,
        v_payload_candidate_value_text::uuid
      );
    END LOOP;

    SELECT COALESCE(
      array_agg(DISTINCT payload_candidate.candidate_id ORDER BY payload_candidate.candidate_id),
      ARRAY[]::uuid[]
    )
    INTO v_payload_candidate_ids
    FROM unnest(v_payload_candidate_ids) AS payload_candidate(candidate_id);
  END IF;

  v_payload_candidate_id_text := NULLIF(
    BTRIM(COALESCE(v_payload_json->>'candidate_id', '')),
    ''
  );

  IF v_payload_candidate_id_text IS NOT NULL THEN
    IF v_payload_candidate_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_ID_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_ID_INVALID',
                'job_id', v_job_row.id::text,
                'candidate_id', v_payload_candidate_id_text
              )::text;
    END IF;

    v_payload_candidate_id := v_payload_candidate_id_text::uuid;
  END IF;

  v_cursor_candidate_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'last_candidate_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'after_candidate_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'candidate_id', '')), '')
  );

  IF v_cursor_candidate_id_text IS NOT NULL THEN
    IF v_cursor_candidate_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CURSOR_INVALID',
                'job_id', v_job_row.id::text,
                'cursor_json', v_cursor_json
              )::text;
    END IF;

    v_cursor_candidate_id := v_cursor_candidate_id_text::uuid;
  END IF;

  v_reason := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload_json->>'reason', '')), ''),
    'DIRTY_FANOUT:' || v_scope_kind
  );
  v_trigger_table := NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', '')), '');
  v_trigger_op := NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', '')), '');

  WITH candidate_pool AS (
    SELECT historical_candidate.candidate_id
    FROM unnest(v_payload_candidate_ids) AS historical_candidate(candidate_id)
    WHERE historical_candidate.candidate_id IS NOT NULL

    UNION

    SELECT v_payload_candidate_id AS candidate_id
    WHERE v_payload_candidate_id IS NOT NULL

    UNION

    SELECT derived_payload_candidate.candidate_id
    FROM public._pay_workbench_candidate_serial_candidate_ids(v_job_row.candidate_id, v_payload_json) AS derived_payload_candidate(candidate_id)
    WHERE derived_payload_candidate.candidate_id IS NOT NULL

    UNION

    SELECT contract_scope.candidate_id
    FROM public.contracts AS contract_scope
    WHERE v_scope_kind = 'CONTRACT'
      AND contract_scope.id = v_scope_id
      AND contract_scope.candidate_id IS NOT NULL

    UNION

    SELECT client_contract.candidate_id
    FROM public.contracts AS client_contract
    WHERE v_scope_kind = 'CLIENT'
      AND client_contract.client_id = v_scope_id
      AND client_contract.candidate_id IS NOT NULL

    UNION

    SELECT umbrella_candidate.id
    FROM public.candidates AS umbrella_candidate
    WHERE v_scope_kind = 'UMBRELLA'
      AND umbrella_candidate.umbrella_id = v_scope_id
  ),
  ordered_candidates AS (
    SELECT candidate_pool.candidate_id,
           ROW_NUMBER() OVER (ORDER BY candidate_pool.candidate_id) AS candidate_ordinal
    FROM candidate_pool
    WHERE candidate_pool.candidate_id IS NOT NULL
      AND (
        v_cursor_candidate_id IS NULL
        OR candidate_pool.candidate_id > v_cursor_candidate_id
      )
    ORDER BY candidate_pool.candidate_id
    LIMIT (v_limit + 1)
  ),
  selected_candidates AS (
    SELECT ordered_candidates.candidate_id,
           ordered_candidates.candidate_ordinal
    FROM ordered_candidates
    WHERE ordered_candidates.candidate_ordinal <= v_limit
  )
  SELECT
    COALESCE(
      array_agg(
        selected_candidates.candidate_id
        ORDER BY selected_candidates.candidate_id
      ),
      ARRAY[]::uuid[]
    ),
    COALESCE(COUNT(*)::integer, 0),
    EXISTS (
      SELECT 1
      FROM ordered_candidates AS extra_candidate
      WHERE extra_candidate.candidate_ordinal > v_limit
    ),
    (
      SELECT last_selected.candidate_id
      FROM selected_candidates AS last_selected
      ORDER BY last_selected.candidate_id DESC
      LIMIT 1
    )
  INTO
    v_candidate_ids,
    v_candidate_count,
    v_has_more,
    v_last_candidate_id
  FROM selected_candidates;

  v_candidate_ids_json := COALESCE(to_jsonb(v_candidate_ids), '[]'::jsonb);

  IF v_has_more AND v_last_candidate_id IS NOT NULL THEN
    v_next_cursor_json := jsonb_build_object(
      'last_candidate_id', v_last_candidate_id::text,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text
    );
  ELSE
    v_next_cursor_json := NULL::jsonb;
  END IF;

  IF COALESCE(v_candidate_count, 0) = 0 THEN
    PERFORM pg_catalog.set_config('cloudtms.banking_pay_inherited_scope_generation', COALESCE(v_saved_inherited_scope_generation, ''), true);
    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_job_row.id::text,
      'job_type', v_job_row.job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text,
      'reason', v_reason,
      'limit', v_limit,
      'cursor_json', v_cursor_json,
      'candidate_ids', '[]'::jsonb,
      'candidate_count', 0,
      'processed_count', 0,
      'affected_scope_count', 0,
      'affected_session_count', 0,
      'enqueued_count', 0,
      'has_more', false,
      'next_cursor', NULL::jsonb,
      'next_cursor_json', NULL::jsonb,
      'candidate_line_calculation_performed', false
    );
  END IF;

  v_gate_allowed_candidate_ids := ARRAY[]::uuid[];
  v_gate_blocked := false;
  v_gate_blocked_candidate_id := NULL::uuid;
  v_gate_last_allowed_candidate_id := NULL::uuid;

  FOREACH v_gate_candidate_id IN ARRAY v_candidate_ids
  LOOP
    v_gate_result := public._pay_workbench_candidate_serial_try_gate(
      p_job_id => v_job_row.id,
      p_candidate_id => v_gate_candidate_id,
      p_job_type => v_job_row.job_type,
      p_payload_json => v_payload_json || jsonb_build_object(
        'candidate_id', v_gate_candidate_id::text,
        'candidate_serial_candidate_id', v_gate_candidate_id::text,
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_gate_candidate_id),
        'fanout_scope_kind', v_scope_kind,
        'fanout_scope_id', v_scope_id::text,
        'cursor_json', v_cursor_json
      ),
      p_reason => 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_GATE'
    );

    IF lower(BTRIM(COALESCE(v_gate_result->>'blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(v_gate_result->>'allowed', 'true'))) IN ('false', 'f', '0', 'no', 'n', 'off') THEN
      v_gate_blocked := true;
      v_gate_blocked_candidate_id := v_gate_candidate_id;
      EXIT;
    END IF;

    v_gate_allowed_candidate_ids := array_append(v_gate_allowed_candidate_ids, v_gate_candidate_id);
    v_gate_last_allowed_candidate_id := v_gate_candidate_id;
  END LOOP;

  IF v_gate_blocked IS TRUE THEN
    SELECT COALESCE(array_agg(DISTINCT allowed_candidate.candidate_id ORDER BY allowed_candidate.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM unnest(COALESCE(v_gate_allowed_candidate_ids, ARRAY[]::uuid[])) AS allowed_candidate(candidate_id)
    WHERE allowed_candidate.candidate_id IS NOT NULL;

    v_candidate_count := COALESCE(array_length(v_candidate_ids, 1), 0);
    v_candidate_ids_json := COALESCE(to_jsonb(v_candidate_ids), '[]'::jsonb);
    v_has_more := true;
    v_last_candidate_id := v_gate_last_allowed_candidate_id;

    v_next_cursor_json := jsonb_strip_nulls(
      CASE
        WHEN v_gate_last_allowed_candidate_id IS NOT NULL THEN
          jsonb_build_object(
            'last_candidate_id', v_gate_last_allowed_candidate_id::text,
            'scope_kind', v_scope_kind,
            'scope_id', v_scope_id::text
          )
        ELSE
          COALESCE(v_cursor_json, '{}'::jsonb)
          || jsonb_build_object(
            'scope_kind', v_scope_kind,
            'scope_id', v_scope_id::text
          )
      END
      || jsonb_build_object(
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'candidate_serial_blocked_at_utc', v_now::text,
        'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED'),
        'candidate_serial_delayed', true
      )
    );

    PERFORM public._pay_workbench_candidate_serial_audit(
      'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED',
      v_job_row.id,
      v_gate_blocked_candidate_id,
      COALESCE(v_gate_result, '{}'::jsonb) || jsonb_build_object(
        'job_type', v_job_row.job_type,
        'scope_kind', v_scope_kind,
        'scope_id', v_scope_id::text,
        'cursor_json', v_cursor_json,
        'next_cursor_json', v_next_cursor_json,
        'allowed_before_block_count', COALESCE(v_candidate_count, 0),
        'blocked_candidate_preserved', true,
        'candidate_mutation_skipped_for_blocked_candidate', true
      ),
      'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED',
      NULL::uuid
    );

    IF COALESCE(v_candidate_count, 0) = 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS delayed_job
      SET payload_json = public._pay_workbench_dirty_payload_merge(
            COALESCE(delayed_job.payload_json, '{}'::jsonb),
            jsonb_build_object(
              'candidate_serial_delayed', true,
              'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
              'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED'),
              'next_cursor_json', v_next_cursor_json,
              'cursor_json', v_next_cursor_json,
              'has_more', true,
              'rerun_required', true,
              'candidate_mutation_skipped_for_blocked_candidate', true,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
          updated_at_utc = v_now
      WHERE delayed_job.id = v_job_row.id;

      PERFORM pg_catalog.set_config('cloudtms.banking_pay_inherited_scope_generation', COALESCE(v_saved_inherited_scope_generation, ''), true);
      RETURN jsonb_build_object(
        'ok', true,
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'scope_kind', v_scope_kind,
        'scope_id', v_scope_id::text,
        'reason', v_reason,
        'limit', v_limit,
        'cursor_json', v_cursor_json,
        'candidate_ids', '[]'::jsonb,
        'candidate_count', 0,
        'processed_count', 0,
        'affected_scope_count', 0,
        'affected_session_count', 0,
        'enqueued_count', 0,
        'has_more', true,
        'next_cursor', v_next_cursor_json,
        'next_cursor_json', v_next_cursor_json,
        'candidate_serial_delayed', true,
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'candidate_mutation_skipped_for_blocked_candidate', true,
        'candidate_line_calculation_performed', false
      );
    END IF;
  END IF;

  CREATE TEMPORARY TABLE IF NOT EXISTS pay_workbench_dirty_fanout_candidates (
    candidate_id uuid PRIMARY KEY,
    source_change_seq bigint NOT NULL DEFAULT 0
  ) ON COMMIT DROP;

  CREATE TEMPORARY TABLE IF NOT EXISTS pay_workbench_dirty_fanout_affected_scope (
    session_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    PRIMARY KEY (session_id, candidate_id)
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.pay_workbench_dirty_fanout_candidates;
  TRUNCATE TABLE pg_temp.pay_workbench_dirty_fanout_affected_scope;

  INSERT INTO pg_temp.pay_workbench_dirty_fanout_candidates (
    candidate_id,
    source_change_seq
  )
  SELECT page_candidate.candidate_id,
         0::bigint
  FROM unnest(v_candidate_ids) AS page_candidate(candidate_id)
  ON CONFLICT (candidate_id) DO NOTHING;

  WITH exact_pairs AS (
    SELECT active_state.candidate_id,active_state.timesheet_id
    FROM private.banking_pay_workbench_timesheet_scope_state active_state
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates fanout_candidate
      ON fanout_candidate.candidate_id=active_state.candidate_id
    WHERE active_state.economic_state IN ('DIRTY','LIVE')
    UNION
    SELECT source_owner.candidate_id,source_owner.timesheet_id
    FROM public.banking_pay_workbench_candidate_source_lines source_owner
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates fanout_candidate
      ON fanout_candidate.candidate_id=source_owner.candidate_id
    WHERE source_owner.status IN ('CURRENT','DIRTY') AND source_owner.timesheet_id IS NOT NULL
  ), complete_pairs AS (
    SELECT candidate_id,timesheet_id FROM exact_pairs
    UNION ALL
    SELECT fanout_candidate.candidate_id,NULL::uuid
    FROM pg_temp.pay_workbench_dirty_fanout_candidates fanout_candidate
    WHERE NOT EXISTS(SELECT 1 FROM exact_pairs WHERE exact_pairs.candidate_id=fanout_candidate.candidate_id)
  )
  SELECT array_agg(candidate_id ORDER BY candidate_id,timesheet_id NULLS FIRST),
         array_agg(timesheet_id ORDER BY candidate_id,timesheet_id NULLS FIRST)
  INTO v_invalidation_candidate_ids,v_invalidation_timesheet_ids
  FROM complete_pairs;

  IF COALESCE(v_job_row.payload_json->>'scope_change_tx_token','')
     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_scope_change_tx_token:=(v_job_row.payload_json->>'scope_change_tx_token')::uuid;
  END IF;
  v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
    COALESCE(v_invalidation_candidate_ids,ARRAY[]::uuid[]),
    COALESCE(v_invalidation_timesheet_ids,ARRAY[]::uuid[]),
    v_reason,v_scope_change_tx_token,
    COALESCE(v_job_row.payload_json,'{}'::jsonb)||jsonb_build_object(
      'skip_candidate_job_enqueue',true,'inherited_scope_generation',v_job_row.scope_change_generation)
  );

  WITH bumped_counters AS (
    INSERT INTO public.app_change_counters AS candidate_counter (
      entity_key,
      seq,
      updated_at
    )
    SELECT
      'pay_candidate:' || fanout_candidate.candidate_id::text,
      1::bigint,
      v_now
    FROM pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
    ON CONFLICT (entity_key)
    DO UPDATE
    SET seq = candidate_counter.seq + 1,
        updated_at = v_now
    RETURNING candidate_counter.entity_key,
              candidate_counter.seq
  )
  UPDATE pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
  SET source_change_seq = bumped_counter.seq
  FROM bumped_counters AS bumped_counter
  WHERE bumped_counter.entity_key = 'pay_candidate:' || fanout_candidate.candidate_id::text;

  WITH candidate_open_scope AS (
    SELECT
      scope_row.session_id,
      scope_row.candidate_id,
      open_session.actor_user_id,
      open_session.pay_date,
      MAX(open_session.pay_date) OVER (
        PARTITION BY open_session.actor_user_id
      ) AS latest_actor_open_pay_date
    FROM public.banking_pay_workbench_session_scope AS scope_row
    JOIN public.banking_pay_workbench_sessions AS open_session
      ON open_session.id = scope_row.session_id
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
      ON fanout_candidate.candidate_id = scope_row.candidate_id
    WHERE open_session.status = 'OPEN'
      AND open_session.discarded_at_utc IS NULL
  ),
  affected_scope AS (
    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET status = 'SOURCE_BUILD_PENDING',
        dirty = true,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    FROM candidate_open_scope AS target_scope
    WHERE target_scope.session_id = scope_update.session_id
      AND target_scope.candidate_id = scope_update.candidate_id
      AND target_scope.pay_date = target_scope.latest_actor_open_pay_date
    RETURNING scope_update.session_id,
              scope_update.candidate_id
  )
  INSERT INTO pg_temp.pay_workbench_dirty_fanout_affected_scope (
    session_id,
    candidate_id
  )
  SELECT affected_scope.session_id,
         affected_scope.candidate_id
  FROM affected_scope
  ON CONFLICT (session_id, candidate_id) DO NOTHING;

  GET DIAGNOSTICS v_affected_scope_count = ROW_COUNT;

  WITH affected_session_summary AS (
    SELECT
      affected_scope.session_id,
      COUNT(*)::integer AS affected_candidate_count,
      (array_agg(
        affected_scope.candidate_id
        ORDER BY affected_scope.candidate_id DESC
      ))[1] AS last_candidate_id
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    GROUP BY affected_scope.session_id
  ),
  updated_sessions AS (
    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET progress_state = 'DIRTY',
        scope_pending_count = GREATEST(
          COALESCE(session_update.scope_pending_count, 0),
          1
        ),
        candidate_sample_rows_json = jsonb_build_array(
          jsonb_build_object(
            'candidate_id', affected_summary.last_candidate_id::text,
            'status', 'SOURCE_BUILD_PENDING',
            'reason', v_reason
          )
        ),
        progress_json = jsonb_strip_nulls(
          COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_dirty_candidate_id', affected_summary.last_candidate_id::text,
            'last_dirty_reason', v_reason,
            'last_dirty_at_utc', v_now::text,
            'last_dirty_fanout_job_id', v_job_row.id::text,
            'last_dirty_fanout_scope_kind', v_scope_kind,
            'last_dirty_fanout_scope_id', v_scope_id::text,
            'last_dirty_fanout_candidate_count', affected_summary.affected_candidate_count
          )
        ),
        progress_counter_version = COALESCE(session_update.progress_counter_version, 0)
          + affected_summary.affected_candidate_count,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    FROM affected_session_summary AS affected_summary
    WHERE session_update.id = affected_summary.session_id
    RETURNING session_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_affected_session_count
  FROM updated_sessions;

  WITH dirtied_source_rows AS (
    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
    SET status = 'DIRTY',
        source_row_json = jsonb_strip_nulls(
          COALESCE(source_line.source_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'dirty_fanout_job_id', v_job_row.id::text,
            'dirty_fanout_scope_kind', v_scope_kind,
            'dirty_fanout_scope_id', v_scope_id::text,
            'dirty_trigger_table', v_trigger_table,
            'dirty_trigger_operation', v_trigger_op,
            'dirty_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    WHERE source_line.session_id = affected_scope.session_id
      AND source_line.candidate_id = affected_scope.candidate_id
      AND source_line.status = 'CURRENT'
    RETURNING source_line.id
  )
  SELECT COUNT(*)::integer
  INTO v_source_rows_marked_dirty_count
  FROM dirtied_source_rows;

  WITH upserted_jobs AS (
    INSERT INTO public.banking_pay_workbench_jobs AS refresh_job (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      economic_build_id,
      private_stage,
      private_cursor_kind,
      private_cursor_json,
      private_stage_version,
      created_at_utc,
      updated_at_utc,
      started_at_utc,
      completed_at_utc,
      failed_at_utc,
      last_error_json
    )
    SELECT
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'QUEUED',
      44,
      v_now,
      0,
      8,
      'WORKBENCH_CANDIDATE_SOURCE_BUILD:'
        || open_session.id::text
        || ':'
        || affected_scope.candidate_id::text
        || ':v'
        || COALESCE(open_session.version, 0)::text
        || ':s'
        || COALESCE(fanout_candidate.source_change_seq, 0)::text
        || ':snapshot:'
        || open_session.source_snapshot_run_id::text
        || ':signature:'
        || md5(COALESCE(open_session.session_signature, ''))
        || ':source_build:'
        || source_build_identity.source_build_run_id::text
        || ':cursor:START',
      open_session.source_snapshot_run_id,
      open_session.id,
      affected_scope.candidate_id,
      jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_operation', v_trigger_op,
        'trigger_op', v_trigger_op,
        'scope_kind', 'CANDIDATE',
        'scope_id', affected_scope.candidate_id::text,
        'candidate_id', affected_scope.candidate_id::text,
        'reason', v_reason,
        'source_change_seq', fanout_candidate.source_change_seq,
        'source_change_sequence', fanout_candidate.source_change_seq,
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(affected_scope.candidate_id),
        'candidate_serial_candidate_id', affected_scope.candidate_id::text,
        'candidate_serial_active_chain_id', COALESCE(NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'candidate_serial_active_chain_id', '')), ''), v_job_row.id::text),
        'candidate_serial_source_job_id', v_job_row.id::text,
        'candidate_serial_reason', 'CANDIDATE_SERIAL_FANOUT_SOURCE_BUILD_QUEUED'
      )
      || jsonb_build_object(
        'targeted_timesheet_ids', '[]'::jsonb,
        'linked_timesheet_ids', '[]'::jsonb,
        'session_id', open_session.id::text,
        'source_session_id', open_session.id::text,
        'session_version', COALESCE(open_session.version, 0),
        'session_signature', open_session.session_signature,
        'snapshot_run_id', open_session.source_snapshot_run_id::text,
        'source_snapshot_run_id', open_session.source_snapshot_run_id::text,
        'source_build_run_id', source_build_identity.source_build_run_id::text,
        'source_fanout_job_id', v_job_row.id::text
      )
      || jsonb_build_object(
        'fanout_scope_kind', v_scope_kind,
        'fanout_scope_id', v_scope_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'source_build_required', true,
        'line_work_required', true,
        'line_work_only', false,
        'source_build_action', 'BUILD_SOURCE',
        'line_work_action', 'SOURCE_BUILD',
        'pay_channel_scope', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(open_session.filters_json->>'pay_channel_scope', open_session.filters_json#>>'{filters,pay_channel_scope}', ''))), ''), 'ALL'),
        'limit', v_limit,
        'source_build_limit', v_limit,
        'source_rows_marked_dirty_count', COALESCE(v_source_rows_marked_dirty_count, 0)
      ),
      NULL::uuid,
      'BUILD_INITIALISE',
      'BUILD_INITIALISE',
      '{}'::jsonb,
      1,
      v_now,
      v_now,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::jsonb
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    JOIN public.banking_pay_workbench_sessions AS open_session
      ON open_session.id = affected_scope.session_id
     AND open_session.status = 'OPEN'
     AND open_session.discarded_at_utc IS NULL
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
      ON fanout_candidate.candidate_id = affected_scope.candidate_id
    CROSS JOIN LATERAL (
      SELECT md5(concat_ws(':',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        open_session.source_snapshot_run_id::text,
        open_session.id::text,
        affected_scope.candidate_id::text,
        COALESCE(open_session.version, 0)::text,
        COALESCE(fanout_candidate.source_change_seq, 0)::text,
        'CANDIDATE_FULL_LIVE',
        v_scope_kind,
        v_scope_id::text,
        v_reason
      )) AS source_build_hash
    ) AS source_build_hash
    CROSS JOIN LATERAL (
      SELECT (
        substr(source_build_hash.source_build_hash, 1, 8) || '-' ||
        substr(source_build_hash.source_build_hash, 9, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 13, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 17, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 21, 12)
      )::uuid AS source_build_run_id
    ) AS source_build_identity
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(refresh_job.priority, EXCLUDED.priority),
        run_at_utc = LEAST(refresh_job.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = public._pay_workbench_merge_targeted_scope_payload(
          COALESCE(refresh_job.payload_json, '{}'::jsonb),
          COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        ),
        updated_at_utc = v_now
    RETURNING refresh_job.id
  )
  SELECT COUNT(*)::integer
  INTO v_jobs_queued_or_reused
  FROM upserted_jobs;

  PERFORM pg_catalog.set_config('cloudtms.banking_pay_inherited_scope_generation', COALESCE(v_saved_inherited_scope_generation, ''), true);
  RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_job_row.id::text,
      'job_type', v_job_row.job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text,
      'reason', v_reason,
      'trigger_table', v_trigger_table,
      'trigger_op', v_trigger_op,
      'limit', v_limit,
      'cursor_json', v_cursor_json,
      'candidate_ids', v_candidate_ids_json,
      'candidate_count', COALESCE(v_candidate_count, 0),
      'processed_count', COALESCE(v_candidate_count, 0),
      'affected_scope_count', COALESCE(v_affected_scope_count, 0),
      'affected_session_count', COALESCE(v_affected_session_count, 0),
      'enqueued_count', COALESCE(v_jobs_queued_or_reused, 0),
      'jobs_queued_or_reused', COALESCE(v_jobs_queued_or_reused, 0),
      'source_rows_marked_dirty_count', COALESCE(v_source_rows_marked_dirty_count, 0),
      'first_stage_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    )
    || jsonb_build_object(
      'has_more', COALESCE(v_has_more, false),
      'candidate_serial_delayed', COALESCE(v_gate_blocked, false),
      'candidate_serial_blocked_candidate_id', CASE WHEN v_gate_blocked_candidate_id IS NULL THEN NULL::text ELSE v_gate_blocked_candidate_id::text END,
      'next_cursor', v_next_cursor_json,
      'next_cursor_json', v_next_cursor_json,
      'last_candidate_id', CASE
        WHEN v_last_candidate_id IS NULL THEN NULL::text
        ELSE v_last_candidate_id::text
      END,
      'candidate_line_calculation_performed', false,
      'session_created', false,
      'rpc_fanout_performed', false
    );
END;
$function$;

-- [REPLACES] public.pay_workbench_scope_change_tx_token_v1()  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_change_tx_token_v1()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_token uuid;
  v_state text;
BEGIN
  IF LOWER(BTRIM(COALESCE(current_setting('cloudtms.scope_generation_finalising', true), 'false')))
       IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RETURN NULL::uuid;
  END IF;

  BEGIN
    v_token := NULLIF(BTRIM(COALESCE(
      current_setting('cloudtms.banking_pay_scope_tx_token', true),
      ''
    )), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID'
      USING ERRCODE = 'P0001';
  END;

  -- This finalizer seals transaction-wide collected work. Under an IMMEDIATE
  -- entry mode its token INSERT must not finalize before counters/jobs exist.
  -- Defer this internal finalizer only, preserving every other constraint mode.
  SET CONSTRAINTS public.trg_pay_workbench_scope_change_finalize_v1 DEFERRED;

  IF v_token IS NULL THEN
    v_token := gen_random_uuid();
    PERFORM set_config('cloudtms.banking_pay_scope_tx_token', v_token::text, true);
    INSERT INTO public.banking_pay_scope_change_transactions(
      tx_token, state, created_at_utc
    ) VALUES (
      v_token, 'PENDING', clock_timestamp()
    );
    RETURN v_token;
  END IF;

  SELECT scope_tx.state
  INTO v_state
  FROM public.banking_pay_scope_change_transactions AS scope_tx
  WHERE scope_tx.tx_token = v_token;

  IF v_state IN ('FINALIZED', 'NOOP') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_GENERATION_FINALIZED_TOO_EARLY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SCOPE_GENERATION_FINALIZED_TOO_EARLY',
              'state', v_state
            )::text;
  END IF;

  INSERT INTO public.banking_pay_scope_change_transactions(
    tx_token, state, created_at_utc
  ) VALUES (
    v_token, 'PENDING', clock_timestamp()
  ) ON CONFLICT (tx_token) DO NOTHING;

  RETURN v_token;
END;
$function$;

-- [REPLACES] public.timesheet_authorise_generic_atomic(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_actor_user_id uuid, p_now_utc timestamp with time zone, p_expected_row_signature text)  winner piece A2
CREATE OR REPLACE FUNCTION public.timesheet_authorise_generic_atomic(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_actor_user_id uuid, p_now_utc timestamp with time zone DEFAULT now(), p_expected_row_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamp with time zone := COALESCE(p_now_utc, now());
  v_requested_ts public.timesheets%ROWTYPE;
  v_current_ts public.timesheets%ROWTYPE;
  v_current_tsfin public.timesheets_financials%ROWTYPE;
  v_contract_week public.contract_weeks%ROWTYPE;
  v_prev_status public.ts_fin_processing_status_enum := NULL;
  v_new_status public.ts_fin_processing_status_enum := NULL;
  v_before_signature_json jsonb := '{}'::jsonb;
  v_after_signature_json jsonb := '{}'::jsonb;
  v_current_row_signature text := NULL;
  v_expected_row_signature text := NULL;
  v_after_row_signature text := NULL;
  v_has_segment_invoice_lock boolean := false;
  v_validation_status text := NULL;
  v_validation_pre_validated boolean := false;
  v_validation_ok boolean := false;
  v_contract_requires_hr boolean := false;
  v_client_requires_hr boolean := false;
  v_hr_validation_required_for_invoice boolean := false;
  v_must_hold_for_hr_validation boolean := false;
  v_prevalidated_fast_track boolean := false;
  v_force_ready_for_invoice boolean := false;
  v_error_state text := NULL;
  v_error_message text := NULL;
  v_diag_started_at timestamptz := clock_timestamp();
  v_temp_log_enabled boolean := false;
  v_advance_state_refresh_json jsonb := '{}'::jsonb;
  v_has_uncleared_advance_override boolean := false;
  v_duplicate_expense_review jsonb := '{}'::jsonb;
BEGIN

  if coalesce((public._ctms_import_correction_classify_v1(p_timesheet_id)
       ->> 'is_import_authoritative_correction')::boolean, false) then
    return jsonb_build_object(
      'ok', false,
      'error_code', 'IMPORT_CORRECTION_UNIT_REQUIRES_BULK_LIFECYCLE',
      'timesheet_id', p_timesheet_id,
      'required_rpc', case when 'AUTHORISE' = 'AUTHORISE'
        then 'timesheet_authorise_bulk_atomic' else 'timesheet_unauthorise_bulk_atomic' end
    );
  end if;
  PERFORM set_config('lock_timeout', '300ms', true);

  BEGIN
    SELECT COALESCE(sd.temp_log, false)
      INTO v_temp_log_enabled
    FROM public.settings_defaults AS sd
    ORDER BY sd.id
    LIMIT 1;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_temp_log_enabled := false;
    WHEN OTHERS THEN
      v_temp_log_enabled := false;
  END;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    p_timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'entry',
      'timesheet_id', p_timesheet_id,
      'expected_timesheet_id', p_expected_timesheet_id,
      'actor_user_id_present', p_actor_user_id IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF p_timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'INVALID_PAYLOAD', DETAIL = jsonb_build_object('field', 'p_timesheet_id')::text;
  END IF;
  IF p_expected_timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'INVALID_PAYLOAD', DETAIL = jsonb_build_object('field', 'p_expected_timesheet_id')::text;
  END IF;
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'INVALID_PAYLOAD', DETAIL = jsonb_build_object('field', 'p_actor_user_id')::text;
  END IF;

  SELECT ts.*
    INTO v_requested_ts
  FROM public.timesheets AS ts
  WHERE ts.timesheet_id = p_timesheet_id
  LIMIT 1
  FOR UPDATE;

  IF v_requested_ts.timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TARGET_NOT_FOUND', DETAIL = jsonb_build_object('timesheet_id', p_timesheet_id)::text;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_requested_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'requested_timesheet_resolved',
      'timesheet_id', v_requested_ts.timesheet_id,
      'is_current', COALESCE(v_requested_ts.is_current, false),
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF COALESCE(v_requested_ts.is_current, false) THEN
    v_current_ts := v_requested_ts;
  ELSE
    SELECT ts.*
      INTO v_current_ts
    FROM public.timesheets AS ts
    WHERE ts.booking_id = v_requested_ts.booking_id
      AND ts.is_current = true
    ORDER BY ts.version DESC NULLS LAST, ts.updated_at DESC NULLS LAST, ts.created_at DESC NULLS LAST, ts.timesheet_id DESC
    LIMIT 1
    FOR UPDATE;
    IF v_current_ts.timesheet_id IS NULL THEN
      v_current_ts := v_requested_ts;
    END IF;
  END IF;

  IF p_expected_timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id THEN
    RAISE EXCEPTION USING MESSAGE = 'EXPECTED_TIMESHEET_MISMATCH', DETAIL = jsonb_build_object('expected_timesheet_id', p_expected_timesheet_id, 'current_timesheet_id', v_current_ts.timesheet_id)::text;
  END IF;

  v_duplicate_expense_review:=private._timesheet_duplicate_expense_review_v1(
    v_current_ts.timesheet_id
  );
  IF COALESCE((v_duplicate_expense_review->>'required')::boolean,false)
     AND COALESCE(current_setting('cloudtms.duplicate_expense_reviewed',true),'')<>'true' THEN
    RAISE EXCEPTION 'DUPLICATE_EXPENSE_REVIEW_REQUIRED'
      USING ERRCODE='PT409',DETAIL=jsonb_build_object(
        'code','DUPLICATE_EXPENSE_REVIEW_REQUIRED',
        'timesheet_id',v_current_ts.timesheet_id,
        'categories',COALESCE(v_duplicate_expense_review->'categories','[]'::jsonb)
      )::text;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'current_timesheet_locked',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  SELECT tf.*
    INTO v_current_tsfin
  FROM public.timesheets_financials AS tf
  WHERE tf.timesheet_id = v_current_ts.timesheet_id
    AND tf.is_current = true
  ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.updated_at DESC NULLS LAST, tf.created_at DESC NULLS LAST, tf.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_current_tsfin.id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TARGET_NOT_FOUND', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'reason', 'NO_TSFIN')::text;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'tsfin_locked',
      'timesheet_id', v_current_ts.timesheet_id,
      'tsfin_id', v_current_tsfin.id,
      'old_processing_status', v_current_tsfin.processing_status::text,
      'old_authorised_present', v_current_tsfin.authorised_at_utc IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF v_current_ts.contract_id IS NOT NULL THEN
    SELECT COALESCE(c.requires_hr, false)
      INTO v_contract_requires_hr
    FROM public.contracts AS c
    WHERE c.id = v_current_ts.contract_id
    LIMIT 1;
  END IF;

  IF private._candidate_expense_source_family_v1(v_current_ts.timesheet_id) THEN
SELECT
  COALESCE((authority.settings_json#>>'{values,requires_hr}')::boolean,false) AS client_requires_hr,
  (ts.timesheet_id IS NOT NULL
    AND COALESCE((authority.settings_json#>>'{values,hr_validation_required_for_invoice}')::boolean,false)
    AND NOT COALESCE((authority.settings_json#>>'{values,no_timesheet_required}')::boolean,false)
    AND COALESCE(tf.total_hours,0)>0) AS hr_validation_required_for_invoice,
  UPPER(vl.status::text) AS validation_status
INTO v_client_requires_hr, v_hr_validation_required_for_invoice, v_validation_status
FROM public.timesheets ts
LEFT JOIN public.contract_weeks cw ON cw.timesheet_id=ts.timesheet_id
LEFT JOIN public.contracts ct ON ct.id=COALESCE(ts.contract_id,cw.contract_id)
LEFT JOIN LATERAL (
  SELECT f.client_id,f.total_hours FROM public.timesheets_financials f
  WHERE f.timesheet_id=ts.timesheet_id AND f.is_current=true
  ORDER BY f.created_at DESC LIMIT 1
) tf ON true
CROSS JOIN LATERAL (
  SELECT private._contract_settings_effective_core_v1(
    COALESCE(tf.client_id,ct.client_id),COALESCE(ts.contract_id,cw.contract_id),
    COALESCE((ts.worked_start_iso AT TIME ZONE 'Europe/London')::date,
      (ts.scheduled_start_iso AT TIME ZONE 'Europe/London')::date,ts.week_ending_date),
    CASE WHEN ts.sheet_scope='DAILY'::public.timesheet_scope_enum THEN 'DAILY' ELSE 'FINANCE' END,
    ts.timesheet_id) AS settings_json
) authority
LEFT JOIN LATERAL (
  SELECT tv.status FROM public.timesheet_validations tv
  WHERE tv.timesheet_id=ts.timesheet_id ORDER BY tv.created_at DESC LIMIT 1
) vl ON true
WHERE ts.timesheet_id=v_current_ts.timesheet_id AND ts.is_current=true
LIMIT 1
;
  ELSE
  -- Exact current-root flags only. Do not rebuild the summary of every
  -- Timesheet to authorise one root; retain the same dated/frozen settings,
  -- current-financial selection and latest-validation semantics.
  WITH bpay_authorisation_point_flags AS MATERIALIZED (
    SELECT ts.timesheet_id, COALESCE(tf.total_hours,0) AS total_hours,
      public.contract_settings_effective_get_v1(
        COALESCE(tf.client_id,ct.client_id),COALESCE(ts.contract_id,cw.contract_id),
        COALESCE((ts.worked_start_iso AT TIME ZONE 'Europe/London')::date,
          (ts.scheduled_start_iso AT TIME ZONE 'Europe/London')::date,ts.week_ending_date),
        CASE WHEN ts.sheet_scope='DAILY'::public.timesheet_scope_enum THEN 'DAILY' ELSE 'FINANCE' END,
        ts.timesheet_id) AS settings_json,
      UPPER(vl.status::text) AS validation_status
    FROM public.timesheets ts
    LEFT JOIN public.contract_weeks cw ON cw.timesheet_id=ts.timesheet_id
    LEFT JOIN public.contracts ct ON ct.id=COALESCE(ts.contract_id,cw.contract_id)
    LEFT JOIN LATERAL (
      SELECT f.client_id,f.total_hours FROM public.timesheets_financials f
      WHERE f.timesheet_id=ts.timesheet_id AND f.is_current=true
      ORDER BY f.created_at DESC LIMIT 1
    ) tf ON true
    LEFT JOIN LATERAL (
      SELECT tv.status FROM public.timesheet_validations tv
      WHERE tv.timesheet_id=ts.timesheet_id ORDER BY tv.created_at DESC LIMIT 1
    ) vl ON true
    WHERE ts.timesheet_id=v_current_ts.timesheet_id AND ts.is_current=true
    LIMIT 1
  )
  SELECT COALESCE((point.settings_json#>>'{values,requires_hr}')::boolean,false),
    (point.timesheet_id IS NOT NULL
      AND COALESCE((point.settings_json#>>'{values,hr_validation_required_for_invoice}')::boolean,false)
      AND NOT COALESCE((point.settings_json#>>'{values,no_timesheet_required}')::boolean,false)
      AND point.total_hours>0),
    point.validation_status
  INTO v_client_requires_hr,v_hr_validation_required_for_invoice,v_validation_status
  FROM bpay_authorisation_point_flags point;
  END IF;

  v_client_requires_hr := COALESCE(v_client_requires_hr, v_contract_requires_hr, false);
  v_hr_validation_required_for_invoice := COALESCE(v_hr_validation_required_for_invoice, v_contract_requires_hr, false);

  IF private._candidate_expense_source_family_v1(v_current_ts.timesheet_id) THEN
    SELECT cw.* INTO v_contract_week FROM public.contract_weeks cw
    WHERE cw.timesheet_id=v_current_ts.timesheet_id FOR UPDATE;
  ELSE
  SELECT cw.*
    INTO v_contract_week
  FROM public.contract_weeks AS cw
  WHERE cw.timesheet_id = v_current_ts.timesheet_id
     OR EXISTS (
       SELECT 1
       FROM public.timesheets AS cw_ts
       WHERE cw_ts.timesheet_id = cw.timesheet_id
         AND cw_ts.booking_id = v_current_ts.booking_id
     )
  ORDER BY CASE WHEN cw.timesheet_id = v_current_ts.timesheet_id THEN 0 ELSE 1 END,
           cw.updated_at DESC NULLS LAST,
           cw.id DESC
  LIMIT 1
  FOR UPDATE;
  END IF;

  IF v_current_ts.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum AND v_contract_week.id IS NULL THEN
    RAISE EXCEPTION USING
      MESSAGE = 'TARGET_NOT_FOUND',
      DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'reason', 'CONTRACT_WEEK_NOT_FOUND_FOR_WEEKLY_TIMESHEET')::text;
  END IF;

  IF v_contract_week.id IS NOT NULL AND v_contract_week.status = 'INVOICED'::public.contract_week_status_enum THEN
    RAISE EXCEPTION USING
      MESSAGE = 'TIMESHEET_LOCKED_BY_INVOICE',
      DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', v_contract_week.id, 'contract_week_status', v_contract_week.status::text, 'lock_scope', 'contract_week_status')::text;
  END IF;

  IF v_contract_week.id IS NOT NULL AND v_contract_week.status = 'CANCELLED'::public.contract_week_status_enum THEN
    RAISE EXCEPTION USING
      MESSAGE = 'CONTRACT_WEEK_NOT_AUTHORISABLE',
      DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', v_contract_week.id, 'contract_week_status', v_contract_week.status::text)::text;
  END IF;

  v_prev_status := v_current_tsfin.processing_status;

  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      CASE
        WHEN v_current_tsfin.invoice_breakdown_json IS NULL THEN '[]'::jsonb
        WHEN jsonb_typeof(v_current_tsfin.invoice_breakdown_json) = 'array' THEN v_current_tsfin.invoice_breakdown_json
        WHEN jsonb_typeof(v_current_tsfin.invoice_breakdown_json) = 'object'
         AND jsonb_typeof(v_current_tsfin.invoice_breakdown_json -> 'segments') = 'array' THEN v_current_tsfin.invoice_breakdown_json -> 'segments'
        ELSE '[]'::jsonb
      END
    ) AS invoice_segment(segment_json)
    WHERE NULLIF(BTRIM(COALESCE(invoice_segment.segment_json ->> 'invoice_locked_invoice_id', '')), '') IS NOT NULL
  ) INTO v_has_segment_invoice_lock;

  IF v_current_ts.archived_at_utc IS NOT NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_ARCHIVED', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id)::text;
  END IF;

  IF v_current_tsfin.locked_by_invoice_id IS NOT NULL OR COALESCE(v_has_segment_invoice_lock, false) THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_LOCKED_BY_INVOICE', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'invoice_id', v_current_tsfin.locked_by_invoice_id)::text;
  END IF;

  IF v_current_ts.authorised_at_server IS NOT NULL OR v_current_tsfin.authorised_at_utc IS NOT NULL OR v_contract_week.status = 'AUTHORISED'::public.contract_week_status_enum THEN
    RAISE EXCEPTION USING MESSAGE = 'ALREADY_AUTHORISED', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END)::text;
  END IF;

  v_before_signature_json := public.timesheet_lifecycle_guard_signature_v1(v_current_ts.timesheet_id, CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, COALESCE(v_temp_log_enabled, false));
  v_current_row_signature := NULLIF(BTRIM(COALESCE(v_before_signature_json ->> 'backend_row_signature', v_before_signature_json ->> 'row_signature', v_before_signature_json ->> 'signature', '')), '');
  v_expected_row_signature := NULLIF(BTRIM(COALESCE(p_expected_row_signature, '')), '');
  IF v_expected_row_signature IS NOT NULL AND COALESCE(v_current_row_signature, '') IS DISTINCT FROM v_expected_row_signature THEN
    IF COALESCE(v_temp_log_enabled, false) THEN
      PERFORM public._temp_diag_log(
        'TIMESHEET_LIFECYCLE_SIGNATURE_DIAG',
        'TEMP_TIMESHEET_LIFECYCLE',
        v_current_ts.timesheet_id::text,
        jsonb_strip_nulls(jsonb_build_object(
          'tag', 'TIMESHEET_LIFECYCLE_SIGNATURE_DIAG',
          'function_name', 'timesheet_authorise_generic_atomic',
          'stage', 'row_signature_mismatch_before_authorise',
          'action', 'authorise',
          'route_family', 'timesheet_lifecycle',
          'timesheet_id', p_timesheet_id,
          'current_timesheet_id', v_current_ts.timesheet_id,
          'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
          'expected_row_signature', v_expected_row_signature,
          'current_row_signature', v_current_row_signature,
          'current_signature_payload', v_before_signature_json,
          'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
        ))
      );
    END IF;
    RAISE EXCEPTION USING MESSAGE = 'ROW_SIGNATURE_MISMATCH', DETAIL = jsonb_build_object('expected_row_signature', v_expected_row_signature, 'current_row_signature', v_current_row_signature, 'current_timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END)::text;
  END IF;

  SELECT COALESCE(tv.pre_validated, false)
    INTO v_validation_pre_validated
  FROM public.timesheet_validations AS tv
  WHERE tv.timesheet_id = v_current_ts.timesheet_id
  ORDER BY tv.updated_at DESC NULLS LAST, tv.created_at DESC NULLS LAST, tv.id DESC
  LIMIT 1;

  IF NOT FOUND THEN
    v_validation_pre_validated := false;
  END IF;

  v_validation_ok := COALESCE(v_validation_status, '') IN ('VALIDATION_OK', 'OVERRIDDEN');
  v_force_ready_for_invoice := v_current_tsfin.basis IN ('NHSP'::public.timesheet_fin_basis_enum, 'NHSP_ADJUSTMENT'::public.timesheet_fin_basis_enum, 'HEALTHROSTER_SELF_BILL'::public.timesheet_fin_basis_enum, 'HEALTHROSTER_ADJUSTMENT'::public.timesheet_fin_basis_enum);
  v_must_hold_for_hr_validation := COALESCE(v_hr_validation_required_for_invoice, false) AND NOT v_validation_ok;
  v_prevalidated_fast_track := COALESCE(v_validation_pre_validated, false) AND v_validation_ok;

  IF v_prev_status NOT IN ('PENDING_AUTH'::public.ts_fin_processing_status_enum, 'READY_FOR_HR'::public.ts_fin_processing_status_enum) THEN
    RAISE EXCEPTION USING MESSAGE = 'AUTHORISE_NOT_ALLOWED', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'processing_status', v_prev_status::text)::text;
  END IF;

  v_new_status := CASE
    WHEN v_force_ready_for_invoice THEN 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
    WHEN v_must_hold_for_hr_validation THEN 'READY_FOR_HR'::public.ts_fin_processing_status_enum
    WHEN v_prevalidated_fast_track THEN 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
    WHEN COALESCE(v_client_requires_hr, false) THEN 'READY_FOR_HR'::public.ts_fin_processing_status_enum
    ELSE 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
  END;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'before_signature_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
      'tsfin_id', v_current_tsfin.id,
      'current_row_signature_present', v_current_row_signature IS NOT NULL,
      'expected_row_signature_present', v_expected_row_signature IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  PERFORM set_config('cloudtms.lifecycle_mutation_context', 'timesheet_authorise', true);
  PERFORM set_config('cloudtms.lifecycle_target_timesheet_id', v_current_ts.timesheet_id::text, true);
  PERFORM set_config('cloudtms.lifecycle_defer_summary_refresh', 'on', true);

  UPDATE public.timesheets AS ts
     SET authorised_at_server = v_now,
         revoked_at = NULL,
         revoked_reason = NULL,
         revoked_by = NULL,
         updated_at = v_now
   WHERE ts.timesheet_id = v_current_ts.timesheet_id
     AND ts.is_current = true
   RETURNING * INTO v_current_ts;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'timesheets_update_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'new_authorised_present', v_current_ts.authorised_at_server IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  UPDATE public.timesheets_financials AS tf
     SET processing_status = v_new_status,
         authorised_by_user_id = p_actor_user_id,
         authorised_at_utc = v_now,
         updated_at = v_now
   WHERE tf.id = v_current_tsfin.id
     AND tf.is_current = true
   RETURNING * INTO v_current_tsfin;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'tsfin_update_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'tsfin_id', v_current_tsfin.id,
      'old_processing_status', v_prev_status::text,
      'new_processing_status', v_current_tsfin.processing_status::text,
      'new_authorised_present', v_current_tsfin.authorised_at_utc IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF v_contract_week.id IS NOT NULL THEN
    UPDATE public.contract_weeks AS cw
       SET status = 'AUTHORISED'::public.contract_week_status_enum,
           updated_at = v_now
     WHERE cw.id = v_contract_week.id
     RETURNING * INTO v_contract_week;
  END IF;

  PERFORM set_config('cloudtms.lifecycle_defer_summary_refresh', 'off', true);

  v_has_uncleared_advance_override := private.bpay_has_uncleared_advance_v1(v_current_ts.timesheet_id);

  IF COALESCE(v_has_uncleared_advance_override, false) THEN
    v_advance_state_refresh_json := public.pay_timesheet_summary_advance_state_refresh(
      p_timesheet_id => v_current_ts.timesheet_id,
      p_actor_user_id => p_actor_user_id
    );

    PERFORM public._temp_diag_log(
      'TEMP_AUTHORISE_STAGE',
      'TEMP_TIMESHEET_LIFECYCLE',
      v_current_ts.timesheet_id::text,
      jsonb_build_object(
        'function_name', 'timesheet_authorise_generic_atomic',
        'stage', 'advance_state_refresh_done',
        'timesheet_id', v_current_ts.timesheet_id,
        'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
        'refresh_result', COALESCE(v_advance_state_refresh_json, '{}'::jsonb),
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );
  ELSE
    PERFORM public._temp_diag_log(
      'TEMP_AUTHORISE_STAGE',
      'TEMP_TIMESHEET_LIFECYCLE',
      v_current_ts.timesheet_id::text,
      jsonb_build_object(
        'function_name', 'timesheet_authorise_generic_atomic',
        'stage', 'advance_state_refresh_skipped',
        'timesheet_id', v_current_ts.timesheet_id,
        'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
        'reason', 'NO_ACTIVE_ADVANCE_THIS_PAYMENT_OVERRIDE',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );
  END IF;

  v_after_signature_json := public.timesheet_lifecycle_guard_signature_v1(v_current_ts.timesheet_id, CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, COALESCE(v_temp_log_enabled, false));
  v_after_row_signature := NULLIF(BTRIM(COALESCE(v_after_signature_json ->> 'backend_row_signature', v_after_signature_json ->> 'row_signature', v_after_signature_json ->> 'signature', '')), '');

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'after_signature_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
      'row_signature_present', v_after_row_signature IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  PERFORM public._audit_insert(
    'timesheet',
    v_current_ts.timesheet_id::text,
    'TIMESHEET_AUTHORISED',
    jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, 'previous_processing_status', v_prev_status::text, 'previous_row_signature', v_current_row_signature),
    jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, 'new_processing_status', v_new_status::text, 'authorised_at_utc', v_now, 'authorised_by_user_id', p_actor_user_id, 'new_row_signature', v_after_row_signature),
    'TIMESHEET_AUTHORISE',
    p_actor_user_id
  );

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'audit_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'return',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
      'new_processing_status', v_new_status::text,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'success', true,
    'operation', 'timesheet_authorise',
    'timesheet_id', v_current_ts.timesheet_id,
    'current_timesheet_id', v_current_ts.timesheet_id,
    'requested_timesheet_id', v_requested_ts.timesheet_id,
    'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
    'booking_id', v_current_ts.booking_id,
    'candidate_id', v_current_tsfin.candidate_id,
    'authorised_at_server', v_current_ts.authorised_at_server,
    'revoked_at', v_current_ts.revoked_at,
    'authorised_at_utc', v_current_tsfin.authorised_at_utc,
    'advance_state_refresh', COALESCE(v_advance_state_refresh_json, '{}'::jsonb),
    'current_version', v_current_ts.version,
    'was_stale', v_requested_ts.timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id,
    'previous_processing_status', v_prev_status::text,
    'processing_status', v_new_status::text,
    'new_processing_status', v_new_status::text,
    'validation_status', v_validation_status,
    'validation_pre_validated', COALESCE(v_validation_pre_validated, false),
    'hr_validation_required_for_invoice', COALESCE(v_hr_validation_required_for_invoice, false),
    'backend_row_signature', v_after_row_signature,
    'row_signature', v_after_row_signature,
    'affected_rows', jsonb_build_array(jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, 'booking_id', v_current_ts.booking_id, 'row_key', 'timesheet:' || v_current_ts.timesheet_id::text)),
    'cache_invalidation_hints', jsonb_build_object('changed_domains', CASE WHEN COALESCE(v_has_uncleared_advance_override, false) THEN jsonb_build_array('timesheets', 'timesheets_financials', 'contract_weeks', 'timesheet_summary_pay_state_cache') ELSE jsonb_build_array('timesheets', 'timesheets_financials', 'contract_weeks') END, 'timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END)
  );
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_error_state = RETURNED_SQLSTATE, v_error_message = MESSAGE_TEXT;
  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    p_timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'exception',
      'timesheet_id', p_timesheet_id,
      'sqlstate', v_error_state,
      'error_message', v_error_message,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );
  IF v_error_state = '55P03' THEN
    RAISE EXCEPTION USING MESSAGE = 'LOCK_TIMEOUT', DETAIL = jsonb_build_object('timesheet_id', p_timesheet_id)::text;
  END IF;
  RAISE;
END;
$function$;

-- [REPLACES] public.weekly_source_first_authorise_v1(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_expected_row_signature text, p_actor_user_id uuid)  winner piece A1_EXTRACT
CREATE OR REPLACE FUNCTION public.weekly_source_first_authorise_v1(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_expected_row_signature text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_lock jsonb;
  v_core jsonb;
  v_canonical uuid;
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;

  if p_timesheet_id is null or p_actor_user_id is null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_FIRST_AUTHORISE_REQUEST_INVALID',
      'retryable',false,'reason','TIMESHEET_AND_ACTOR_REQUIRED');
  end if;

  -- One plain read before the gate, because the gate is pinned to a Candidate.
  -- Nothing is written by it and the identity is re-resolved under the locks.
  v_context:=private.bpay_source_authorise_identity_v1(p_timesheet_id);
  if coalesce((v_context->>'ok')::boolean,false) is not true then
    return v_context;
  end if;

  v_lock:=private.bpay_source_authorise_lock_v1(
    (v_context->>'candidate_id')::uuid,p_timesheet_id,pg_catalog.gen_random_uuid());
  if coalesce((v_lock->>'ok')::boolean,false) is not true then
    return v_lock;
  end if;

  select (family_element.value->>'canonical_timesheet_id')::uuid
    into v_canonical
  from pg_catalog.jsonb_array_elements(coalesce(v_lock->'families','[]'::jsonb))
    as family_element(value)
  where (family_element.value->>'requested_timesheet_id')::uuid=p_timesheet_id;

  if p_expected_timesheet_id is not null
     and p_expected_timesheet_id is distinct from v_canonical then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION',
      'retryable',false,'timesheet_id',p_timesheet_id,
      'canonical_timesheet_id',v_canonical);
  end if;

  v_core:=private.weekly_source_first_authorise_core_v1(
    p_timesheet_id,p_expected_row_signature,p_actor_user_id,v_lock);
  return v_core||pg_catalog.jsonb_build_object('gate',v_lock->>'gate');
end;
$function$;

